def xano_list_instances(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_list_instances"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status_str, credential_used=None, extra=None):
        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict) and extra:
            row.update(extra)
        logs.append(row)
        _save("xano_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("xano_service_limits.json")
        if not isinstance(limits, dict):
            limits = {}
        quota_max = limits.get("quota_max_calls")
        rate_per_min = limits.get("rate_limit_per_minute")

        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        if isinstance(rate_per_min, int) and rate_per_min >= 0:
            cutoff = (now - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= rate_per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota_max, int) and quota_max >= 0:
            if len(logs) >= quota_max:
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    # Validate
    if status is not None and status not in ("active", "disabled", "deleted"):
        err = _err("VALIDATION_ERROR", "Invalid status.", field="status")
        _log_call("error", extra={"error_code": err["error"]["code"]})
        return err
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
        _log_call("error", extra={"error_code": err["error"]["code"]})
        return err
    if cursor is not None and not isinstance(cursor, str):
        err = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        _log_call("error", extra={"error_code": err["error"]["code"]})
        return err

    limit_err = _enforce_limits()
    if limit_err:
        _log_call("error", extra={"error_code": limit_err["error"]["code"]})
        return limit_err

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []

    rows = instances
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # Deterministic ordering: created_at desc then instance_name asc
    def _key(r):
        ca = r.get("created_at")
        if not isinstance(ca, str):
            ca = ""
        iname = r.get("instance_name")
        if not isinstance(iname, str):
            iname = ""
        return (ca, iname)

    rows_sorted = sorted(rows, key=_key, reverse=True)
    total = len(rows_sorted)

    start = 0
    if cursor:
        # cursor format: "i:<offset>"
        if not cursor.startswith("i:"):
            err = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _log_call("error", extra={"error_code": err["error"]["code"]})
            return err
        off_s = cursor[2:]
        if not off_s.isdigit():
            err = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _log_call("error", extra={"error_code": err["error"]["code"]})
            return err
        start = int(off_s)
        if start < 0 or start > total:
            err = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _log_call("error", extra={"error_code": err["error"]["code"]})
            return err

    page = rows_sorted[start:start + limit]
    next_off = start + len(page)
    has_more = next_off < total
    next_cursor = ("i:%d" % next_off) if has_more else None

    resp = {
        "instances": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
    }
    _log_call("ok")
    return resp

