        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        if isinstance(rate_per_min, int) and rate_per_min >= 0:
            cutoff = (now - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= rate_per_min:
