        _log_call("error", extra={"error_code": err["error"]["code"]})
        return err

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
        _log_call("error", extra={"error_code": err["error"]["code"]})
