    if isinstance(workspace_id, int):
        wid = workspace_id
    elif isinstance(workspace_id, str):
        if not workspace_id.isdigit():
            err = _err("VALIDATION_ERROR", "workspace_id must be numeric.", field="workspace_id")
            _log_call("error", extra={"error_code": err["error"]["code"]})
            return err
        wid = int(workspace_id)
    else:
        err = _err("VALIDATION_ERROR", "workspace_id must be an integer or numeric string.", field="workspace_id")
        _log_call("error", extra={"error_code": err["error"]["code"]})
        return err

    if wid <= 0:
        err = _err("VALIDATION_ERROR", "workspace_id must be a positive integer.", field="workspace_id")
        _log_call("error", extra={"error_code": err["error"]["code"]})
        return err

