def xano_list_tables(instance_name, database_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None, meta=None):
        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "xrl_" + uuid.uuid4().hex,
            "endpoint": "xano_list_tables",
            "status": status_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential": credential_used,
            "meta": meta or {}
        }
        logs.append(row)
        _save("xano_request_logs.json", logs)

    def _parse_pos_int(v, field):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if isinstance(v, int):
            n = v
        elif isinstance(v, str) and v.isdigit():
            n = int(v)
        else:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if n <= 0:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        return n, None

    def _decode_cursor(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or c == "":
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset", None)
            if isinstance(off, int) and off >= 0:
                return off, None
        except Exception:
            pass
        return None, _err("VALIDATION_ERROR", "cursor is invalid")

    # Validate inputs
    if not isinstance(instance_name, str) or not instance_name.strip():
        _log("VALIDATION_ERROR", meta={"field": "instance_name"})
        return _err("VALIDATION_ERROR", "instance_name is required and must be a non-empty string")
    db_id, e = _parse_pos_int(database_id, "database_id")
    if e:
        _log("VALIDATION_ERROR", meta={"field": "database_id"})
        return e
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleting", "deleted"):
            _log("VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, deleting, deleted")
    if limit is None:
        limit_n = 50
    else:
        if isinstance(limit, bool) or not isinstance(limit, int):
            _log("VALIDATION_ERROR", meta={"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        if limit < 1 or limit > 200:
            _log("VALIDATION_ERROR", meta={"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_n = limit

    offset, e = _decode_cursor(cursor)
    if e:
        _log("VALIDATION_ERROR", meta={"field": "cursor"})
        return e

    # Resolve active instance
    instances = _load("xano_instances.json")
    inst = None
    for r in instances if isinstance(instances, list) else []:
        if r.get("instance_name") == instance_name:
            inst = r
            break
    if not inst or inst.get("status") != "active":
        _log("NOT_FOUND", meta={"instance_name": instance_name})
        return _err("NOT_FOUND", "Instance not found or not active")

    # Resolve workspace by (instance_id, xano_workspace_id) and status != deleted
    workspaces = _load("xano_workspaces.json")
    ws = None
    for r in workspaces if isinstance(workspaces, list) else []:
        if r.get("instance_id") == inst.get("id") and int(r.get("xano_workspace_id", 0) or 0) == db_id:
            ws = r
            break
    if not ws or ws.get("status") == "deleted":
        _log("NOT_FOUND", meta={"instance_name": instance_name, "database_id": db_id})
        return _err("NOT_FOUND", "Workspace/database not found")

    # "UNAUTHORIZED" only if no combination can serve the call; no explicit credentials exist in schema.
    # For this offline connector, if instance/workspace are active, allow read.
    if ws.get("status") not in ("active", "suspended"):
        _log("UNAUTHORIZED", meta={"workspace_status": ws.get("status")})
        return _err("UNAUTHORIZED", "Not authorized to read workspace schema")

    tables = _load("xano_tables.json")
    rows = []
    for t in tables if isinstance(tables, list) else []:
        if t.get("workspace_id") != ws.get("id"):
            continue
        if t.get("status") == "deleted":
            continue
        if status is not None and t.get("status") != status:
            continue
        rows.append(t)

    # Stable sort: by xano_table_id then id
    def _key(r):
        xt = r.get("xano_table_id")
        try:
            xti = int(xt)
        except Exception:
            xti = 0
        return (xti, str(r.get("id", "")))
    rows.sort(key=_key)

    total = len(rows)
    page = rows[offset:offset + limit_n]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Touch last_discovered_at on instance
    inst_changed = False
    for i, r in enumerate(instances if isinstance(instances, list) else []):
        if r.get("id") == inst.get("id"):
            if r.get("last_discovered_at") != now:
                instances[i] = dict(r)
                instances[i]["last_discovered_at"] = now
                instances[i]["updated_at"] = now if "updated_at" in r else r.get("updated_at")
                inst_changed = True
            break
    if inst_changed:
        _save("xano_instances.json", instances)

    _log("OK", meta={"returned": len(page), "total": total, "has_more": has_more})
    return {
        "tables": page,
        "total": total,
        "limit": limit_n,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more
    }

