def xano_create_table(instance_name, workspace_id, name, description=None, docs=None, auth=None, tag=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_create_table"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error=None, **ctx):
        logs = _ensure_logs()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "context": ctx or {}
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer (string or number).", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer (string or number).", field=field)
        if isinstance(v, float):
            if v.is_integer() and int(v) > 0:
                return int(v), None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer (string or number).", field=field)

    def _is_ulid_prefix(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_")

    def _gen_id(prefix):
        return f"{prefix}_" + uuid.uuid4().hex[:26]

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    # Validate inputs
    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string.", field="description")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if docs is not None and not isinstance(docs, str):
        e = _err("VALIDATION_ERROR", "docs must be a string.", field="docs")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if auth is not None and not isinstance(auth, bool):
        e = _err("VALIDATION_ERROR", "auth must be a boolean.", field="auth")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if tag is not None:
        if not isinstance(tag, list) or any(not isinstance(x, str) for x in tag):
            e = _err("VALIDATION_ERROR", "tag must be an array of strings.", field="tag")
            _log("error", error=e["error"], instance_name=instance_name)
            return e

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    tables = _load("xano_tables.json")
    if not isinstance(tables, list):
        tables = []

    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    # workspace_id may be local ULID OR numeric Xano workspace id (per audit, must accept ULID)
    ws_row = None
    ws_num = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id")), None)
        if not ws_row:
            e = _err("NOT_FOUND", "Workspace not found for this instance.", field="workspace_id")
            _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
            return e
        if ws_row.get("status") == "deleted":
            e = _err("NOT_FOUND", "Workspace is deleted.", field="workspace_id")
            _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
            return e
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
        if not ws_row:
            e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
            _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
            return e

    if ws_row.get("status") != "active":
        e = _err("CONFLICT", f"Workspace is not active (status={ws_row.get('status')}).", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    # Enforce unique(workspace_id, name) where status != 'deleted'
    desired_name = name.strip()
    for t in tables:
        if t.get("workspace_id") == ws_row.get("id") and t.get("status") != "deleted" and t.get("name") == desired_name:
            e = _err("CONFLICT", "A non-deleted table with this name already exists in the workspace.", field="name")
            _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, name=desired_name)
            return e

    now = _now()
    table_row = {
        "id": _gen_id("xnt"),
        "workspace_id": ws_row.get("id"),
        "xano_table_id": max([t.get("xano_table_id") for t in tables if isinstance(t.get("xano_table_id"), int)] + [0]) + 1,
        "name": desired_name,
        "description": description,
        "docs": docs,
        "auth_required": bool(auth) if auth is not None else False,
        "tags": tag if tag is not None else [],
        "status": "active",
        "pk_field_name": "id",
        "pk_next_value": 1,
        "schema": {
            "fields": [
                {"name": "id", "type": "int", "primary_key": True, "nullable": False, "description": "Primary key"}
            ],
            "pk_field_name": "id"
        },
        "indexes": [],
        "created_at": now,
        "updated_at": now
    }

    tables.append(table_row)
    _save("xano_tables.json", tables)

    _log("ok", instance_name=instance_name, workspace_id=workspace_id, table_id=table_row["id"])
    return {"data": table_row}

def xano_update_table(instance_name, workspace_id, table_id, name=None, description=None, docs=None, auth=None, tag=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, meta=None):
        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "xrl_" + uuid.uuid4().hex,
            "endpoint": "xano_update_table",
            "status": status_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential": None,
            "meta": meta or {}
        })
        _save("xano_request_logs.json", logs)

    def _parse_pos_int(v, field):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if isinstance(v, int):
            n = v
        elif isinstance(v, str) and v.isdigit():
            n = int(v)
        else:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if n <= 0:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        return n, None

    # Validate identifiers
    if not isinstance(instance_name, str) or not instance_name.strip():
        _log("VALIDATION_ERROR", meta={"field": "instance_name"})
        return _err("VALIDATION_ERROR", "instance_name is required and must be a non-empty string")
    ws_id, e = _parse_pos_int(workspace_id, "workspace_id")
    if e:
        _log("VALIDATION_ERROR", meta={"field": "workspace_id"})
        return e
    tbl_id, e = _parse_pos_int(table_id, "table_id")
    if e:
        _log("VALIDATION_ERROR", meta={"field": "table_id"})
        return e

    # Validate fields
    if name is not None:
        if not isinstance(name, str) or len(name) < 1:
            _log("VALIDATION_ERROR", meta={"field": "name"})
            return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR", meta={"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string")
    if docs is not None and not isinstance(docs, str):
        _log("VALIDATION_ERROR", meta={"field": "docs"})
        return _err("VALIDATION_ERROR", "docs must be a string")
    if auth is not None and not isinstance(auth, bool):
        _log("VALIDATION_ERROR", meta={"field": "auth"})
        return _err("VALIDATION_ERROR", "auth must be a boolean")
    if tag is not None:
        if not isinstance(tag, list) or any((not isinstance(x, str)) for x in tag):
            _log("VALIDATION_ERROR", meta={"field": "tag"})
            return _err("VALIDATION_ERROR", "tag must be an array of strings")

    if all(v is None for v in (name, description, docs, auth, tag)):
        _log("VALIDATION_ERROR", meta={"field": "body"})
        return _err("VALIDATION_ERROR", "At least one field must be provided to update")

    # Resolve instance/workspace
    instances = _load("xano_instances.json")
    inst = None
    for r in instances if isinstance(instances, list) else []:
        if r.get("instance_name") == instance_name:
            inst = r
            break
    if not inst or inst.get("status") != "active":
        _log("NOT_FOUND", meta={"instance_name": instance_name})
        return _err("NOT_FOUND", "Instance not found or not active")

    workspaces = _load("xano_workspaces.json")
    ws = None
    for r in workspaces if isinstance(workspaces, list) else []:
        if r.get("instance_id") == inst.get("id") and int(r.get("xano_workspace_id", 0) or 0) == ws_id:
            ws = r
            break
    if not ws or ws.get("status") == "deleted":
        _log("NOT_FOUND", meta={"workspace_id": ws_id})
        return _err("NOT_FOUND", "Workspace/database not found")

    if ws.get("status") != "active":
        _log("UNAUTHORIZED", meta={"workspace_status": ws.get("status")})
        return _err("UNAUTHORIZED", "Not authorized to modify tables in this workspace")

    tables = _load("xano_tables.json")
    if not isinstance(tables, list):
        tables = []

    idx = None
    table = None
    for i, t in enumerate(tables):
        if t.get("workspace_id") == ws.get("id") and int(t.get("xano_table_id", 0) or 0) == tbl_id:
            if t.get("status") == "deleted":
                table = None
                idx = None
            else:
                table = t
                idx = i
            break
    if table is None:
        _log("NOT_FOUND", meta={"table_id": tbl_id})
        return _err("NOT_FOUND", "Table not found")

    # Enforce rename uniqueness
    if name is not None and name != table.get("name"):
        for t in tables:
            if t.get("workspace_id") == ws.get("id") and t.get("status") != "deleted" and t.get("name") == name:
                _log("CONFLICT", meta={"name": name})
                return _err("CONFLICT", "A non-deleted table with this name already exists in the workspace")

    updated = dict(table)
    if name is not None:
        updated["name"] = name
    if description is not None:
        updated["description"] = description
    if docs is not None:
        updated["docs"] = docs
    if auth is not None:
        updated["auth_required"] = bool(auth)
    if tag is not None:
        updated["tags"] = tag
    updated["updated_at"] = now

    # Business rule: must not set status to deleted directly (tool doesn't accept status anyway).
    tables[idx] = updated
    _save("xano_tables.json", tables)

    _log("OK", meta={"table_id": tbl_id})
    return {"table": updated}

