        _log("error", "VALIDATION_ERROR", "instance_name is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "instance_name is required and must be a non-empty string")

    # Parse workspace_id / table_id: allow local id or positive int (string/int)
    def _parse_id(val, kind_prefix):
        if isinstance(val, int):
            if val <= 0:
                return None, _err("VALIDATION_ERROR", f"{kind_prefix}_id must be a positive integer")
            return {"mode": "xano_id", "xano_id": val}, None
        if isinstance(val, str):
            s = val.strip()
            if not s:
                return None, _err("VALIDATION_ERROR", f"{kind_prefix}_id is required")
            # local id
            if s.startswith(kind_prefix[:3]):  # "workspace"->"wor" not good; pass explicit prefix below
                # not used
                pass
            # numeric string
            if s.isdigit():
                n = int(s)
                if n <= 0:
                    return None, _err("VALIDATION_ERROR", f"{kind_prefix}_id must be a positive integer")
                return {"mode": "xano_id", "xano_id": n}, None
            # local internal id is accepted as-is
            return {"mode": "local_id", "local_id": s}, None
        return None, _err("VALIDATION_ERROR", f"{kind_prefix}_id must be a string or integer")

    ws_parsed, e = _parse_id(workspace_id, "workspace")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    tb_parsed, e = _parse_id(table_id, "table")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    instances = _load("xano_instances.json")
    inst = next((r for r in instances if r.get("instance_name") == instance_name), None)
    if not inst:
        _log("error", "NOT_FOUND", "Instance not found")
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("status") != "active":
        _log("error", "NOT_FOUND", "Instance is not active")
        return _err("NOT_FOUND", "Instance is not active")
    instance_id = inst.get("id")

    workspaces = _load("xano_workspaces.json")
    def _resolve_workspace():
        if ws_parsed["mode"] == "local_id":
            return next((w for w in workspaces
                         if w.get("id") == ws_parsed["local_id"] and w.get("instance_id") == instance_id), None)
        # xano numeric id
        return next((w for w in workspaces
                     if w.get("instance_id") == instance_id and int(w.get("xano_workspace_id") or 0) == ws_parsed["xano_id"]), None)

    ws = _resolve_workspace()
    if not ws or ws.get("status") == "deleted":
        _log("error", "NOT_FOUND", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log("error", "UNAUTHORIZED", "Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active")

    tables = _load("xano_tables.json")
    workspace_local_id = ws.get("id")

    def _resolve_table():
        if tb_parsed["mode"] == "local_id":
            return next((t for t in tables
                         if t.get("id") == tb_parsed["local_id"] and t.get("workspace_id") == workspace_local_id), None)
        return next((t for t in tables
                     if t.get("workspace_id") == workspace_local_id and int(t.get("xano_table_id") or 0) == tb_parsed["xano_id"]), None)

    tbl = _resolve_table()
    if not tbl or tbl.get("status") == "deleted":
        _log("error", "NOT_FOUND", "Table not found")
        return _err("NOT_FOUND", "Table not found")

    # Enforce lifecycle transitions
    status = tbl.get("status")
    if status == "deleting":
        _log("error", "CONFLICT", "Table is already deleting")
        return _err("CONFLICT", "Table is already deleting")
    if status != "active":
        _log("error", "INVALID_TRANSITION", f"Cannot delete table from status '{status}'")
        return _err("INVALID_TRANSITION", f"Cannot delete table from status '{status}'")

    # Transition active -> deleting -> deleted (as described)
    now = _now()
    # First phase: deleting
    tbl["status"] = "deleting"
    tbl["updated_at"] = now
    # Second phase: deleted
    tbl["status"] = "deleted"
    tbl["updated_at"] = now

    # Persist
    _save("xano_tables.json", tables)

    _log("ok")
    return {
        "table": {
            "id": tbl.get("id"),
            "workspace_id": tbl.get("workspace_id"),
            "xano_table_id": tbl.get("xano_table_id"),
            "name": tbl.get("name"),
            "status": tbl.get("status"),
            "updated_at": tbl.get("updated_at"),
        },
        "result": {"deleted": True}
    }

