            if val <= 0:
                return None, _err("VALIDATION_ERROR", f"{label} must be a positive integer")
            return {"mode": "xano_id", "xano_id": val}, None
        if isinstance(val, str):
            s = val.strip()
            if not s:
                return None, _err("VALIDATION_ERROR", f"{label} is required")
            if s.isdigit():
                n = int(s)
                if n <= 0:
                    return None, _err("VALIDATION_ERROR", f"{label} must be a positive integer")
                return {"mode": "xano_id", "xano_id": n}, None
            return {"mode": "local_id", "local_id": s}, None
        return None, _err("VALIDATION_ERROR", f"{label} must be a string or integer")

    ws_parsed, e = _parse_id(workspace_id, "workspace_id")
