    schema = tbl.get("schema")
    if not isinstance(schema, dict):
        _log("error", "CONFLICT", "Table schema is missing or malformed")
        return _err("CONFLICT", "Table schema is missing or malformed")

    # touch discovery timestamp for instance
    now = _now()
    inst["last_discovered_at"] = now
    inst["updated_at"] = inst.get("updated_at") or now
    _save("xano_instances.json", instances)

    _log("ok")
    return {
        "table": {
            "id": tbl.get("id"),
