        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    tables = _load("xano_tables.json")
    if not isinstance(tables, list):
        tables = []

    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    ws_row = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted"), None)
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    table_row = None
    table_idx = None
    if _is_ulid_prefix(table_id, "xnt"):
        for i, t in enumerate(tables):
            if t.get("id") == table_id and t.get("workspace_id") == ws_row.get("id") and t.get("status") != "deleted":
                table_row, table_idx = t, i
                break
    else:
        tid_num, terr = _as_positive_int(table_id, "table_id")
        if terr:
            _log("error", error=terr["error"], instance_name=instance_name, table_id=table_id)
            return terr
        for i, t in enumerate(tables):
            if t.get("workspace_id") == ws_row.get("id") and t.get("xano_table_id") == tid_num and t.get("status") != "deleted":
                table_row, table_idx = t, i
                break
    if not table_row:
        e = _err("NOT_FOUND", "Table not found.", field="table_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, table_id=table_id)
        return e

    schema = table_row.get("schema")
    if not isinstance(schema, dict):
        schema = {"fields": [], "pk_field_name": table_row.get("pk_field_name") or "id"}
    fields_list = schema.get("fields")
    if not isinstance(fields_list, list):
        fields_list = []

    pk_name = table_row.get("pk_field_name") or schema.get("pk_field_name") or "id"
    if fname == pk_name:
        e = _err("CONFLICT", "Cannot add a field with the same name as the primary key field.", field="field_name")
        _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
        return e

    existing_names = {f.get("name") for f in fields_list if isinstance(f, dict)}
    if fname in existing_names:
        e = _err("CONFLICT", "A field with this name already exists on the table.", field="field_name")
        _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
        return e

    new_field = {"name": fname, "type": field_type}
    if description is not None:
        new_field["description"] = description

    new_schema = copy.deepcopy(schema)
    new_fields = list(fields_list)
    new_fields.append(new_field)
    new_schema["fields"] = new_fields
    new_schema["pk_field_name"] = pk_name

    # Persist
    now = _now()
    tables[table_idx]["schema"] = new_schema
    tables[table_idx]["updated_at"] = now
    _save("xano_tables.json", tables)

    out = copy.deepcopy(tables[table_idx])
    _log("ok", instance_name=instance_name, workspace_id=workspace_id, table_id=table_id, field_name=fname)
    return {"data": {"table": out, "schema": out.get("schema")}}

def xano_rename_schema_field(instance_name, workspace_id, table_id, old_name, new_name, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
