        entry = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "xano_rename_schema_field",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status
        }
        if resolved:
            entry.update(resolved)
        if error_code:
            entry["error_code"] = error_code
        if error_message:
            entry["error_message"] = error_message
        logs.append(entry)
        _save("request_logs.json", logs)

    try:
        if not isinstance(instance_name, str) or not instance_name.strip():
            _log("error", "VALIDATION_ERROR", "instance_name must be a non-empty string")
            return _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        if not isinstance(old_name, str) or not old_name.strip():
            _log("error", "VALIDATION_ERROR", "old_name must be a non-empty string")
            return _err("VALIDATION_ERROR", "old_name must be a non-empty string")
        if not isinstance(new_name, str) or not new_name.strip():
            _log("error", "VALIDATION_ERROR", "new_name must be a non-empty string")
            return _err("VALIDATION_ERROR", "new_name must be a non-empty string")

        old_name_s = old_name.strip()
        new_name_s = new_name.strip()

        if old_name_s == new_name_s:
            _log("error", "VALIDATION_ERROR", "old_name and new_name must be different")
            return _err("VALIDATION_ERROR", "old_name and new_name must be different")

        name_re = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
        if not name_re.match(old_name_s):
            _log("error", "VALIDATION_ERROR", "old_name is not a valid field identifier")
            return _err("VALIDATION_ERROR", "old_name is not a valid field identifier")
        if not name_re.match(new_name_s):
            _log("error", "VALIDATION_ERROR", "new_name is not a valid field identifier")
            return _err("VALIDATION_ERROR", "new_name is not a valid field identifier")

        instances = _load("xano_instances.json")
        inst = None
        for r in instances:
            if r.get("instance_name") == instance_name:
                inst = r
                break
        if not inst or inst.get("status") != "active":
            _log("error", "NOT_FOUND", "Active instance not found", {"instance_name": instance_name})
            return _err("NOT_FOUND", "Active instance not found")

        workspaces = _load("xano_workspaces.json")
        ws = None

        def _parse_pos_int(v):
            if isinstance(v, bool):
                return None
            if isinstance(v, int):
                return v if v > 0 else None
            if isinstance(v, str):
                s = v.strip()
                if s.isdigit():
                    iv = int(s)
                    return iv if iv > 0 else None
            return None

        ws_num = _parse_pos_int(workspace_id)
        if isinstance(workspace_id, str) and ws_num is None:
            # treat as local id
            for r in workspaces:
                if r.get("id") == workspace_id and r.get("instance_id") == inst.get("id") and r.get("status") != "deleted":
                    ws = r
                    break
        else:
            if ws_num is None:
                _log("error", "VALIDATION_ERROR", "workspace_id must be a positive integer or a valid workspace id string")
                return _err("VALIDATION_ERROR", "workspace_id must be a positive integer or a valid workspace id string")
            for r in workspaces:
                if r.get("instance_id") == inst.get("id") and r.get("xano_workspace_id") == ws_num and r.get("status") != "deleted":
                    ws = r
                    break
        if not ws:
            _log("error", "NOT_FOUND", "Workspace not found", {"instance_name": instance_name})
            return _err("NOT_FOUND", "Workspace not found")

        tables = _load("xano_tables.json")
        tbl = None
        table_num = _parse_pos_int(table_id)
        if isinstance(table_id, str) and table_num is None:
            for r in tables:
                if r.get("id") == table_id and r.get("workspace_id") == ws.get("id") and r.get("status") != "deleted":
                    tbl = r
                    break
        else:
            if table_num is None:
                _log("error", "VALIDATION_ERROR", "table_id must be a positive integer or a valid table id string")
                return _err("VALIDATION_ERROR", "table_id must be a positive integer or a valid table id string")
            for r in tables:
                if r.get("workspace_id") == ws.get("id") and r.get("xano_table_id") == table_num and r.get("status") != "deleted":
                    tbl = r
                    break
        if not tbl:
            _log("error", "NOT_FOUND", "Table not found", {"instance_name": instance_name})
            return _err("NOT_FOUND", "Table not found")

        schema = tbl.get("schema")
        if not isinstance(schema, dict):
            _log("error", "CONFLICT", "Table schema is missing or invalid")
            return _err("CONFLICT", "Table schema is missing or invalid")

        pk_field = tbl.get("pk_field_name")
        if old_name_s == pk_field:
            _log("error", "CONFLICT", "Cannot rename the primary key field")
            return _err("CONFLICT", "Cannot rename the primary key field")

        fields_obj = schema.get("fields")
        if not isinstance(fields_obj, list):
            # support alt schema shapes by trying dict of fields
            if isinstance(fields_obj, dict):
                fields_list = [{"name": k, **({"type": v} if isinstance(v, str) else (v if isinstance(v, dict) else {}))} for k, v in fields_obj.items()]
                fields_obj = fields_list
            else:
                _log("error", "CONFLICT", "Schema fields are missing or invalid")
                return _err("CONFLICT", "Schema fields are missing or invalid")

        existing_names = set()
        old_field = None
        for f in fields_obj:
            n = f.get("name")
            if isinstance(n, str):
                existing_names.add(n)
                if n == old_name_s:
                    old_field = f

        if not old_field:
            _log("error", "NOT_FOUND", "Field not found in schema")
            return _err("NOT_FOUND", "Field not found in schema")

        if new_name_s in existing_names:
            _log("error", "CONFLICT", "new_name already exists in schema")
            return _err("CONFLICT", "new_name already exists in schema")

        # apply rename
        old_field["name"] = new_name_s

        # if schema has pk field reference, ensure it isn't broken (pk rename forbidden already)
        # update any index definitions that reference the old field name
        idxs = tbl.get("indexes")
        if not isinstance(idxs, list):
            idxs = []
        for idx in idxs:
            fs = idx.get("fields")
            if isinstance(fs, list):
                for part in fs:
                    if isinstance(part, dict) and part.get("name") == old_name_s:
                        part["name"] = new_name_s

        tbl["schema"] = schema
        tbl["indexes"] = idxs
        tbl["updated_at"] = now

        # persist update in tables list
        updated = False
        for i, r in enumerate(tables):
            if r.get("id") == tbl.get("id"):
                tables[i] = tbl
                updated = True
                break
        if not updated:
            _log("error", "NOT_FOUND", "Table not found for update")
            return _err("NOT_FOUND", "Table not found for update")

        _save("xano_tables.json", tables)

        resolved = {"instance_name": instance_name, "workspace_id": ws.get("id"), "table_id": tbl.get("id")}
        _log("ok", resolved=resolved)
        return {
            "table": tbl,
            "schema": tbl.get("schema")
        }
    except Exception as e:
        _log("error", "CONFLICT", "Unexpected error", {"detail": str(e)})
        return _err("CONFLICT", "Unexpected error", detail=str(e))

def xano_delete_field(instance_name, workspace_id, table_id, field_name, **_extra):
