            _log("error", "VALIDATION_ERROR", "instance_name must be a non-empty string")
            return _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        if not isinstance(field_name, str) or not field_name.strip():
            _log("error", "VALIDATION_ERROR", "field_name must be a non-empty string")
            return _err("VALIDATION_ERROR", "field_name must be a non-empty string")

        fname = field_name.strip()
        name_re = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
        if not name_re.match(fname):
            _log("error", "VALIDATION_ERROR", "field_name is not a valid field identifier")
            return _err("VALIDATION_ERROR", "field_name is not a valid field identifier")

        instances = _load("xano_instances.json")
        inst = None
        for r in instances:
            if r.get("instance_name") == instance_name:
                inst = r
                break
        if not inst or inst.get("status") != "active":
            _log("error", "NOT_FOUND", "Active instance not found", {"instance_name": instance_name})
            return _err("NOT_FOUND", "Active instance not found")

        def _parse_pos_int(v):
            if isinstance(v, bool):
                return None
            if isinstance(v, int):
                return v if v > 0 else None
            if isinstance(v, str):
                s = v.strip()
                if s.isdigit():
                    iv = int(s)
                    return iv if iv > 0 else None
            return None

        workspaces = _load("xano_workspaces.json")
        ws = None
        ws_num = _parse_pos_int(workspace_id)
        if isinstance(workspace_id, str) and ws_num is None:
            for r in workspaces:
                if r.get("id") == workspace_id and r.get("instance_id") == inst.get("id") and r.get("status") != "deleted":
                    ws = r
                    break
        else:
            if ws_num is None:
                _log("error", "VALIDATION_ERROR", "workspace_id must be a positive integer or a valid workspace id string")
                return _err("VALIDATION_ERROR", "workspace_id must be a positive integer or a valid workspace id string")
            for r in workspaces:
                if r.get("instance_id") == inst.get("id") and r.get("xano_workspace_id") == ws_num and r.get("status") != "deleted":
                    ws = r
                    break
        if not ws:
            _log("error", "NOT_FOUND", "Workspace not found", {"instance_name": instance_name})
            return _err("NOT_FOUND", "Workspace not found")

        tables = _load("xano_tables.json")
        tbl = None
        table_num = _parse_pos_int(table_id)
        if isinstance(table_id, str) and table_num is None:
            for r in tables:
                if r.get("id") == table_id and r.get("workspace_id") == ws.get("id") and r.get("status") != "deleted":
                    tbl = r
                    break
        else:
            if table_num is None:
                _log("error", "VALIDATION_ERROR", "table_id must be a positive integer or a valid table id string")
                return _err("VALIDATION_ERROR", "table_id must be a positive integer or a valid table id string")
            for r in tables:
                if r.get("workspace_id") == ws.get("id") and r.get("xano_table_id") == table_num and r.get("status") != "deleted":
                    tbl = r
                    break
        if not tbl:
            _log("error", "NOT_FOUND", "Table not found", {"instance_name": instance_name})
            return _err("NOT_FOUND", "Table not found")

        pk_field = tbl.get("pk_field_name")
        if fname == pk_field:
            _log("error", "CONFLICT", "Cannot delete the primary key field")
            return _err("CONFLICT", "Cannot delete the primary key field")

        schema = tbl.get("schema")
        if not isinstance(schema, dict):
            _log("error", "CONFLICT", "Table schema is missing or invalid")
            return _err("CONFLICT", "Table schema is missing or invalid")

        fields_obj = schema.get("fields")
        if not isinstance(fields_obj, list):
            if isinstance(fields_obj, dict):
                fields_obj = [{"name": k, **({"type": v} if isinstance(v, str) else (v if isinstance(v, dict) else {}))} for k, v in fields_obj.items()]
            else:
                _log("error", "CONFLICT", "Schema fields are missing or invalid")
                return _err("CONFLICT", "Schema fields are missing or invalid")

        # Check field exists and whether constraints block deletion.
        target_idx = None
        for i, f in enumerate(fields_obj):
            if isinstance(f, dict) and f.get("name") == fname:
                target_idx = i
                break
        if target_idx is None:
            _log("error", "NOT_FOUND", "Field not found in schema")
            return _err("NOT_FOUND", "Field not found in schema")

        # Constraint checks:
        # - if indexes reference this field, reject with CONFLICT
        idxs = tbl.get("indexes")
        if not isinstance(idxs, list):
            idxs = []
        for idx in idxs:
            fs = idx.get("fields")
            if isinstance(fs, list):
                for part in fs:
                    if isinstance(part, dict) and part.get("name") == fname:
                        _log("error", "CONFLICT", "Field cannot be removed because an index depends on it")
                        return _err("CONFLICT", "Field cannot be removed because an index depends on it", index_id=idx.get("index_id"))

        # - if schema has explicit constraints listing required fields, enforce
        constraints = schema.get("constraints")
        if isinstance(constraints, list):
            for c in constraints:
                if isinstance(c, dict):
                    # common shapes: {"type":"required","field":"x"} or {"type":"not_null","field":"x"}
                    if c.get("field") == fname and c.get("type") in ("required", "not_null", "fk", "unique"):
                        _log("error", "CONFLICT", "Field cannot be removed due to schema constraints")
                        return _err("CONFLICT", "Field cannot be removed due to schema constraints", constraint=c)
                elif isinstance(c, str):
                    # best-effort: block if mentioned plainly
                    if fname in c and ("required" in c or "not null" in c or "foreign" in c or "unique" in c):
                        _log("error", "CONFLICT", "Field cannot be removed due to schema constraints")
                        return _err("CONFLICT", "Field cannot be removed due to schema constraints", constraint=c)

        # Delete it
        fields_obj.pop(target_idx)
        schema["fields"] = fields_obj
        tbl["schema"] = schema
        tbl["updated_at"] = now

        updated = False
        for i, r in enumerate(tables):
            if r.get("id") == tbl.get("id"):
                tables[i] = tbl
                updated = True
                break
        if not updated:
            _log("error", "NOT_FOUND", "Table not found for update")
            return _err("NOT_FOUND", "Table not found for update")

        _save("xano_tables.json", tables)

        resolved = {"instance_name": instance_name, "workspace_id": ws.get("id"), "table_id": tbl.get("id")}
        _log("ok", resolved=resolved)
        return {
            "table": tbl,
            "schema": tbl.get("schema")
        }
    except Exception as e:
        _log("error", "CONFLICT", "Unexpected error", {"detail": str(e)})
        return _err("CONFLICT", "Unexpected error", detail=str(e))

