                return _err("VALIDATION_ERROR", "table_id must be a positive integer or a valid table id string")
            for r in tables:
                if r.get("workspace_id") == ws.get("id") and r.get("xano_table_id") == table_num and r.get("status") != "deleted":
                    tbl = r
                    break
        if not tbl:
            _log("error", "NOT_FOUND", "Table not found", {"instance_name": instance_name})
            return _err("NOT_FOUND", "Table not found")

        idxs = tbl.get("indexes")
        if idxs is None:
            idxs = []
        if not isinstance(idxs, list):
            _log("error", "CONFLICT", "Table indexes are invalid")
            return _err("CONFLICT", "Table indexes are invalid")

        resolved = {"instance_name": instance_name, "workspace_id": ws.get("id"), "table_id": tbl.get("id")}
        _log("ok", resolved=resolved)
        return {
            "table_id": tbl.get("id"),
            "xano_table_id": tbl.get("xano_table_id"),
            "indexes": idxs,
            "count": len(idxs)
        }
    except Exception as e:
        _log("error", "CONFLICT", "Unexpected error", {"detail": str(e)})
        return _err("CONFLICT", "Unexpected error", detail=str(e))

def xano_create_btree_index(instance_name, workspace_id, table_id, fields, **_extra):
    import json, os, datetime, time, uuid, re, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_create_btree_index"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error=None, **ctx):
        logs = _ensure_logs()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "context": ctx or {}
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, float):
            if v.is_integer() and int(v) > 0:
                return int(v), None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)

    def _is_ulid_prefix(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_")

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    if not isinstance(fields, list) or len(fields) < 1:
        e = _err("VALIDATION_ERROR", "fields must be a non-empty array.", field="fields")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    for i, f in enumerate(fields):
        if not isinstance(f, dict):
            e = _err("VALIDATION_ERROR", "Each fields item must be an object with name and op.", field="fields")
            _log("error", error=e["error"], instance_name=instance_name)
            return e
        if not isinstance(f.get("name"), str) or not f.get("name").strip():
            e = _err("VALIDATION_ERROR", "Each fields item must include a non-empty name.", field="fields")
            _log("error", error=e["error"], instance_name=instance_name)
            return e
        if f.get("op") not in ("asc", "desc"):
            e = _err("VALIDATION_ERROR", "Index field op must be 'asc' or 'desc'.", field="fields")
            _log("error", error=e["error"], instance_name=instance_name)
            return e

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    tables = _load("xano_tables.json")
    if not isinstance(tables, list):
        tables = []
    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    ws_row = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted"), None)
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    table_row = None
    table_idx = None
    if _is_ulid_prefix(table_id, "xnt"):
        for i, t in enumerate(tables):
            if t.get("id") == table_id and t.get("workspace_id") == ws_row.get("id") and t.get("status") != "deleted":
                table_row, table_idx = t, i
                break
    else:
        tid_num, terr = _as_positive_int(table_id, "table_id")
        if terr:
            _log("error", error=terr["error"], instance_name=instance_name, table_id=table_id)
            return terr
        for i, t in enumerate(tables):
            if t.get("workspace_id") == ws_row.get("id") and t.get("xano_table_id") == tid_num and t.get("status") != "deleted":
                table_row, table_idx = t, i
                break
    if not table_row:
        e = _err("NOT_FOUND", "Table not found.", field="table_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, table_id=table_id)
        return e

    schema = table_row.get("schema")
    schema_fields = []
    if isinstance(schema, dict) and isinstance(schema.get("fields"), list):
        schema_fields = [f.get("name") for f in schema.get("fields") if isinstance(f, dict)]
    schema_field_set = set([n for n in schema_fields if isinstance(n, str)])

    for f in fields:
        if f["name"].strip() not in schema_field_set:
            e = _err("VALIDATION_ERROR", f"Unknown field referenced in index: {f['name']}", field="fields")
            _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
            return e

    indexes = table_row.get("indexes")
    if not isinstance(indexes, list):
        indexes = []

    index_id = "idx_" + uuid.uuid4().hex[:16]
    idx_entry = {
        "index_id": index_id,
        "type": "btree",
        "fields": [{"name": f["name"].strip(), "op": f["op"]} for f in fields],
        "created_at": _now(),
        "status": "active"
    }

    new_indexes = copy.deepcopy(indexes)
    new_indexes.append(idx_entry)
    now = _now()
    tables[table_idx]["indexes"] = new_indexes
    tables[table_idx]["updated_at"] = now
    _save("xano_tables.json", tables)

    _log("ok", instance_name=instance_name, workspace_id=workspace_id, table_id=table_id, index_id=index_id)
    return {"data": idx_entry}

def xano_create_unique_index(instance_name, workspace_id, table_id, fields, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _to_pos_int(v, name):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be a positive integer")
        if isinstance(v, int):
            n = v
        elif isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"\d+", s):
                try:
                    n = int(s)
                except Exception:
                    return None, _err("VALIDATION_ERROR", f"{name} must be a positive integer")
            else:
                return None, None  # means "not numeric id"
        else:
            return None, _err("VALIDATION_ERROR", f"{name} must be a string or integer")
        if n <= 0:
            return None, _err("VALIDATION_ERROR", f"{name} must be a positive integer")
        return n, None

    def _resolve_instance(instances):
        if not isinstance(instance_name, str) or not instance_name.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        rows = [r for r in instances if r.get("instance_name") == instance_name]
        if not rows:
            return None, _err("NOT_FOUND", "Instance not found", instance_name=instance_name)
        active = [r for r in rows if r.get("status") == "active"]
        if not active:
            st = rows[0].get("status")
            return None, _err("NOT_FOUND", "Instance is not active", instance_name=instance_name, status=st)
        if len(active) != 1:
            return None, _err("CONFLICT", "Multiple active instances found for instance_name", instance_name=instance_name)
        return active[0], None

    def _resolve_workspace(workspaces, instance_row):
        # workspace_id can be local id (string not purely digits) or numeric xano_workspace_id (string digits/int)
        if isinstance(workspace_id, str) and not workspace_id.strip():
            return None, _err("VALIDATION_ERROR", "workspace_id must be a non-empty string or integer")
        if not isinstance(workspace_id, (str, int)) or isinstance(workspace_id, bool):
            return None, _err("VALIDATION_ERROR", "workspace_id must be a string or integer")
        inst_id = instance_row.get("id")
        # local id path
        if isinstance(workspace_id, str) and not re.fullmatch(r"\d+", workspace_id.strip()):
            ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst_id), None)
            if not ws or ws.get("status") == "deleted":
                return None, _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
            return ws, None
        # numeric id path
        n, e = _to_pos_int(workspace_id, "workspace_id")
        if e:
            return None, e
        ws = next((w for w in workspaces if w.get("instance_id") == inst_id and int(w.get("xano_workspace_id") or 0) == n and w.get("status") != "deleted"), None)
        if not ws:
            return None, _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        return ws, None

    def _resolve_table(tables, ws_row):
        if isinstance(table_id, str) and not table_id.strip():
            return None, _err("VALIDATION_ERROR", "table_id must be a non-empty string or integer")
        if not isinstance(table_id, (str, int)) or isinstance(table_id, bool):
            return None, _err("VALIDATION_ERROR", "table_id must be a string or integer")
        ws_id = ws_row.get("id")
        if isinstance(table_id, str) and not re.fullmatch(r"\d+", table_id.strip()):
            tb = next((t for t in tables if t.get("id") == table_id and t.get("workspace_id") == ws_id), None)
            if not tb or tb.get("status") == "deleted":
                return None, _err("NOT_FOUND", "Table not found", table_id=table_id)
            return tb, None
        n, e = _to_pos_int(table_id, "table_id")
        if e:
            return None, e
        tb = next((t for t in tables if t.get("workspace_id") == ws_id and int(t.get("xano_table_id") or 0) == n and t.get("status") != "deleted"), None)
        if not tb:
            return None, _err("NOT_FOUND", "Table not found", table_id=table_id)
        return tb, None

    def _ensure_usage_log(logs, endpoint, status, latency_ms, context):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        row.update({k: v for k, v in (context or {}).items() if v is not None})
        logs.append(row)

    # Validate fields
    if not isinstance(fields, list) or len(fields) < 1:
        status = "error"
        instances = _load("xano_instances.json")
        logs = _load("xano_request_logs.json")
        _ensure_usage_log(logs, "xano_create_unique_index", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
        _save("xano_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "fields must be a non-empty array")

    norm_fields = []
    for i, f in enumerate(fields):
        if not isinstance(f, dict):
            status = "error"
            instances = _load("xano_instances.json")
            logs = _load("xano_request_logs.json")
            _ensure_usage_log(logs, "xano_create_unique_index", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
            _save("xano_request_logs.json", logs)
            return _err("VALIDATION_ERROR", f"fields[{i}] must be an object")
        name = f.get("name")
        op = f.get("op")
        if not isinstance(name, str) or not name.strip():
            status = "error"
            instances = _load("xano_instances.json")
            logs = _load("xano_request_logs.json")
            _ensure_usage_log(logs, "xano_create_unique_index", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
            _save("xano_request_logs.json", logs)
            return _err("VALIDATION_ERROR", f"fields[{i}].name must be a non-empty string")
        if op not in ("asc", "desc"):
            status = "error"
            instances = _load("xano_instances.json")
            logs = _load("xano_request_logs.json")
            _ensure_usage_log(logs, "xano_create_unique_index", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
            _save("xano_request_logs.json", logs)
            return _err("VALIDATION_ERROR", f"fields[{i}].op must be 'asc' or 'desc'")
        norm_fields.append({"name": name, "op": op})

    instances = _load("xano_instances.json")
    workspaces = _load("xano_workspaces.json")
    tables = _load("xano_tables.json")
    records = _load("xano_table_records.json")
    logs = _load("xano_request_logs.json")

    inst, e = _resolve_instance(instances)
    if e:
        status = "error"
        _ensure_usage_log(logs, "xano_create_unique_index", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name})
        _save("xano_request_logs.json", logs)
        return e

    ws, e = _resolve_workspace(workspaces, inst)
    if e:
        status = "error"
        _ensure_usage_log(logs, "xano_create_unique_index", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id})
        _save("xano_request_logs.json", logs)
        return e

    tb, e = _resolve_table(tables, ws)
    if e:
        status = "error"
        _ensure_usage_log(logs, "xano_create_unique_index", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
        _save("xano_request_logs.json", logs)
        return e

    if tb.get("status") != "active":
        status = "error"
        _ensure_usage_log(logs, "xano_create_unique_index", "INVALID_TRANSITION", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
        _save("xano_request_logs.json", logs)
        return _err("INVALID_TRANSITION", "Cannot modify indexes unless table is active", table_status=tb.get("status"))

    schema = tb.get("schema")
    if not isinstance(schema, dict):
        status = "error"
        _ensure_usage_log(logs, "xano_create_unique_index", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
        _save("xano_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "Table schema is invalid or missing")

    # collect schema field names
    field_names = set()
    if isinstance(schema.get("fields"), list):
        for sf in schema["fields"]:
            if isinstance(sf, dict) and isinstance(sf.get("name"), str):
                field_names.add(sf["name"])
    # also include pk field if present
    if isinstance(tb.get("pk_field_name"), str):
        field_names.add(tb["pk_field_name"])

    missing = [f["name"] for f in norm_fields if f["name"] not in field_names]
    if missing:
        status = "error"
        _ensure_usage_log(logs, "xano_create_unique_index", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
        _save("xano_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "Index references fields not present in schema", missing_fields=missing)

    idxs = tb.get("indexes")
    if not isinstance(idxs, list):
        idxs = []
        tb["indexes"] = idxs

    # idempotency / conflict detection
    desired_sig = ("unique", tuple((f["name"], f["op"]) for f in norm_fields))
    for ix in idxs:
        if not isinstance(ix, dict):
            continue
        if ix.get("status") == "deleted":
            continue
        ix_type = ix.get("type")
        ix_fields = ix.get("fields")
        if ix_type in ("unique", "btree_unique", "unique_index") and isinstance(ix_fields, list):
            sig = ("unique", tuple((a.get("name"), a.get("op")) for a in ix_fields if isinstance(a, dict)))
            if sig == desired_sig:
                # already exists -> return existing (idempotent)
                _ensure_usage_log(logs, "xano_create_unique_index", "success", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
                _save("xano_request_logs.json", logs)
                return {
                    "index": ix,
                    "indexes": idxs,
                    "table_id": tb.get("id"),
                    "xano_table_id": tb.get("xano_table_id"),
                }

    # Enforce uniqueness across existing active records
    tb_id = tb.get("id")
    active_recs = [r for r in records if r.get("table_id") == tb_id and r.get("status") == "active"]
    seen = {}
    for r in active_recs:
        rd = r.get("record_data") if isinstance(r.get("record_data"), dict) else {}
        key = []
        for f in norm_fields:
            key.append(rd.get(f["name"]))
        key_t = tuple(key)
        if key_t in seen:
            status = "error"
            _ensure_usage_log(logs, "xano_create_unique_index", "CONFLICT", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
            _save("xano_request_logs.json", logs)
            return _err(
                "CONFLICT",
                "Cannot create unique index: existing records violate uniqueness",
                fields=[f["name"] for f in norm_fields],
                conflicting_records=[{"pk_value": seen[key_t], "pk_value_2": r.get("pk_value")}],
            )
        seen[key_t] = r.get("pk_value")

    # generate new numeric index_id
    max_id = 0
    for ix in idxs:
        if isinstance(ix, dict):
            try:
                v = ix.get("index_id")
                if isinstance(v, str) and re.fullmatch(r"\d+", v):
                    v = int(v)
                if isinstance(v, int) and v > max_id:
                    max_id = v
            except Exception:
                pass
    new_index_id = max_id + 1

    new_ix = {
        "index_id": new_index_id,
        "type": "unique",
        "name": None,
        "fields": norm_fields,
        "lang": None,
        "status": "active",
        "created_at": _now(),
    }
    idxs.append(new_ix)
    tb["updated_at"] = _now()
    _save("xano_tables.json", tables)

    _ensure_usage_log(logs, "xano_create_unique_index", "success", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
    _save("xano_request_logs.json", logs)

    return {
        "index": new_ix,
        "indexes": tb.get("indexes", []),
        "table_id": tb.get("id"),
        "xano_table_id": tb.get("xano_table_id"),
    }

def xano_create_search_index(instance_name, workspace_id, table_id, name, lang, fields, **_extra):
    import json, os, datetime, time, uuid, re, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_create_search_index"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error=None, **ctx):
        logs = _ensure_logs()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "context": ctx or {}
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, float):
            if v.is_integer() and int(v) > 0:
                return int(v), None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)

    def _is_ulid_prefix(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_")

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if not isinstance(lang, str) or not lang.strip():
        e = _err("VALIDATION_ERROR", "lang must be a non-empty string.", field="lang")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if not isinstance(fields, list) or len(fields) < 1:
        e = _err("VALIDATION_ERROR", "fields must be a non-empty array.", field="fields")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    for f in fields:
        if not isinstance(f, dict) or not isinstance(f.get("name"), str) or not f.get("name").strip():
            e = _err("VALIDATION_ERROR", "Each fields item must be an object with non-empty name and integer priority.", field="fields")
            _log("error", error=e["error"], instance_name=instance_name)
            return e
        if not isinstance(f.get("priority"), int):
            e = _err("VALIDATION_ERROR", "Each fields item priority must be an integer.", field="fields")
            _log("error", error=e["error"], instance_name=instance_name)
            return e

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    tables = _load("xano_tables.json")
    if not isinstance(tables, list):
        tables = []
    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    ws_row = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted"), None)
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    table_row = None
    table_idx = None
    if _is_ulid_prefix(table_id, "xnt"):
        for i, t in enumerate(tables):
            if t.get("id") == table_id and t.get("workspace_id") == ws_row.get("id") and t.get("status") != "deleted":
                table_row, table_idx = t, i
                break
    else:
        tid_num, terr = _as_positive_int(table_id, "table_id")
        if terr:
            _log("error", error=terr["error"], instance_name=instance_name, table_id=table_id)
            return terr
        for i, t in enumerate(tables):
            if t.get("workspace_id") == ws_row.get("id") and t.get("xano_table_id") == tid_num and t.get("status") != "deleted":
                table_row, table_idx = t, i
                break
    if not table_row:
        e = _err("NOT_FOUND", "Table not found.", field="table_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, table_id=table_id)
        return e

    schema = table_row.get("schema")
    schema_fields = []
    if isinstance(schema, dict) and isinstance(schema.get("fields"), list):
        schema_fields = [f.get("name") for f in schema.get("fields") if isinstance(f, dict)]
    schema_field_set = set([n for n in schema_fields if isinstance(n, str)])

    for f in fields:
        if f["name"].strip() not in schema_field_set:
            e = _err("VALIDATION_ERROR", f"Unknown field referenced in search index: {f['name']}", field="fields")
            _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
            return e

    indexes = table_row.get("indexes")
    if not isinstance(indexes, list):
        indexes = []

    index_id = "sidx_" + uuid.uuid4().hex[:16]
    idx_entry = {
        "index_id": index_id,
        "type": "search",
        "name": name.strip(),
        "lang": lang.strip(),
        "fields": [{"name": f["name"].strip(), "priority": int(f["priority"])} for f in fields],
        "created_at": _now(),
        "status": "active"
    }

    new_indexes = copy.deepcopy(indexes)
    new_indexes.append(idx_entry)
    now = _now()
    tables[table_idx]["indexes"] = new_indexes
    tables[table_idx]["updated_at"] = now
    _save("xano_tables.json", tables)

    _log("ok", instance_name=instance_name, workspace_id=workspace_id, table_id=table_id, index_id=index_id)
    return {"data": idx_entry}

def xano_delete_index(instance_name, workspace_id, table_id, index_id, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _to_pos_int(v, name_):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{name_} must be a positive integer")
        if isinstance(v, int):
            n = v
        elif isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"\d+", s):
                try:
                    n = int(s)
                except Exception:
                    return None, _err("VALIDATION_ERROR", f"{name_} must be a positive integer")
            else:
                return None, _err("VALIDATION_ERROR", f"{name_} must be a positive integer")
        else:
            return None, _err("VALIDATION_ERROR", f"{name_} must be a string or integer")
        if n <= 0:
            return None, _err("VALIDATION_ERROR", f"{name_} must be a positive integer")
        return n, None

    def _ensure_usage_log(logs, endpoint, status, latency_ms, context):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        row.update({k: v for k, v in (context or {}).items() if v is not None})
        logs.append(row)

    def _resolve_instance(instances):
        if not isinstance(instance_name, str) or not instance_name.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        rows = [r for r in instances if r.get("instance_name") == instance_name]
        if not rows:
            return None, _err("NOT_FOUND", "Instance not found", instance_name=instance_name)
        active = [r for r in rows if r.get("status") == "active"]
        if not active:
            return None, _err("NOT_FOUND", "Instance is not active", instance_name=instance_name, status=rows[0].get("status"))
        if len(active) != 1:
            return None, _err("CONFLICT", "Multiple active instances found for instance_name", instance_name=instance_name)
        return active[0], None

    def _resolve_workspace(workspaces, instance_row):
        if isinstance(workspace_id, str) and not workspace_id.strip():
            return None, _err("VALIDATION_ERROR", "workspace_id must be a non-empty string or integer")
        if not isinstance(workspace_id, (str, int)) or isinstance(workspace_id, bool):
            return None, _err("VALIDATION_ERROR", "workspace_id must be a string or integer")
        inst_id = instance_row.get("id")
        if isinstance(workspace_id, str) and not re.fullmatch(r"\d+", workspace_id.strip()):
            ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst_id), None)
            if not ws or ws.get("status") == "deleted":
                return None, _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
            return ws, None
        n, e = _to_pos_int(workspace_id, "workspace_id")
        if e:
            return None, e
        ws = next((w for w in workspaces if w.get("instance_id") == inst_id and int(w.get("xano_workspace_id") or 0) == n and w.get("status") != "deleted"), None)
        if not ws:
            return None, _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        return ws, None

    def _resolve_table(tables, ws_row):
        if isinstance(table_id, str) and not table_id.strip():
            return None, _err("VALIDATION_ERROR", "table_id must be a non-empty string or integer")
        if not isinstance(table_id, (str, int)) or isinstance(table_id, bool):
            return None, _err("VALIDATION_ERROR", "table_id must be a string or integer")
        ws_id = ws_row.get("id")
        if isinstance(table_id, str) and not re.fullmatch(r"\d+", table_id.strip()):
            tb = next((t for t in tables if t.get("id") == table_id and t.get("workspace_id") == ws_id), None)
            if not tb or tb.get("status") == "deleted":
                return None, _err("NOT_FOUND", "Table not found", table_id=table_id)
            return tb, None
        n, e = _to_pos_int(table_id, "table_id")
        if e:
            return None, e
        tb = next((t for t in tables if t.get("workspace_id") == ws_id and int(t.get("xano_table_id") or 0) == n and t.get("status") != "deleted"), None)
        if not tb:
            return None, _err("NOT_FOUND", "Table not found", table_id=table_id)
        return tb, None

    idx_id, e = _to_pos_int(index_id, "index_id")
    if e:
        logs = _load("xano_request_logs.json")
        _ensure_usage_log(logs, "xano_delete_index", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
        _save("xano_request_logs.json", logs)
        return e

    instances = _load("xano_instances.json")
    workspaces = _load("xano_workspaces.json")
    tables = _load("xano_tables.json")
    logs = _load("xano_request_logs.json")

    inst, e = _resolve_instance(instances)
    if e:
        _ensure_usage_log(logs, "xano_delete_index", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name})
        _save("xano_request_logs.json", logs)
        return e

    ws, e = _resolve_workspace(workspaces, inst)
    if e:
        _ensure_usage_log(logs, "xano_delete_index", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id})
        _save("xano_request_logs.json", logs)
        return e

    tb, e = _resolve_table(tables, ws)
    if e:
        _ensure_usage_log(logs, "xano_delete_index", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
        _save("xano_request_logs.json", logs)
        return e

    if tb.get("status") != "active":
        _ensure_usage_log(logs, "xano_delete_index", "INVALID_TRANSITION", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
        _save("xano_request_logs.json", logs)
        return _err("INVALID_TRANSITION", "Cannot modify indexes unless table is active", table_status=tb.get("status"))

    idxs = tb.get("indexes")
    if not isinstance(idxs, list):
        idxs = []
        tb["indexes"] = idxs

    # Find index
    found = None
    for ix in idxs:
        if isinstance(ix, dict):
            v = ix.get("index_id")
            try:
                if isinstance(v, str) and re.fullmatch(r"\d+", v):
                    v = int(v)
            except Exception:
                pass
            if v == idx_id and ix.get("status") != "deleted":
                found = ix
                break

    if not found:
        _ensure_usage_log(logs, "xano_delete_index", "NOT_FOUND", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id, "index_id": idx_id})
        _save("xano_request_logs.json", logs)
        return _err("NOT_FOUND", "Index not found", index_id=idx_id)

    # Mark deleted (preserve history)
    found["status"] = "deleted"
    found["deleted_at"] = _now()
    tb["updated_at"] = _now()
    _save("xano_tables.json", tables)

    _ensure_usage_log(logs, "xano_delete_index", "success", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id, "index_id": idx_id})
    _save("xano_request_logs.json", logs)

    return {
        "deleted": True,
        "index_id": idx_id,
        "indexes": tb.get("indexes", []),
        "table_id": tb.get("id"),
        "xano_table_id": tb.get("xano_table_id"),
    }

