    def _resolve_table(tables, ws_row):
        if isinstance(table_id, str) and not table_id.strip():
            return None, _err("VALIDATION_ERROR", "table_id must be a non-empty string or integer")
        if not isinstance(table_id, (str, int)) or isinstance(table_id, bool):
