        if not tb:
            return None, _err("NOT_FOUND", "Table not found", table_id=table_id)
        return tb, None

    def _get_path(d, path):
        if not isinstance(d, dict):
            return None
        cur = d
        for p in path.split("."):
            if not isinstance(cur, dict) or p not in cur:
                return None
            cur = cur[p]
        return cur

    def _coerce_num(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, (int, float)):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x.strip())
            except Exception:
                return None
        return None

    def _match_condition(record, cond):
        # Supports common shapes:
        # - {"field": "name", "op": "eq"|"ne"|"gt"|"gte"|"lt"|"lte"|"contains"|"starts_with"|"ends_with"|"in"|"exists", "value": ...}
        # - {"and": [cond, ...]} / {"or": [cond, ...]} / {"not": cond}
        if not isinstance(cond, dict):
            return False
        if "and" in cond:
            a = cond.get("and")
            if not isinstance(a, list):
                return False
            return all(_match_condition(record, c) for c in a)
        if "or" in cond:
            a = cond.get("or")
            if not isinstance(a, list):
                return False
            return any(_match_condition(record, c) for c in a)
        if "not" in cond:
            return not _match_condition(record, cond.get("not"))

        field = cond.get("field")
        op = cond.get("op") or cond.get("operator")
        value = cond.get("value")
        if not isinstance(field, str) or not field.strip():
            return False
        if not isinstance(op, str) or not op.strip():
            return False

        rd = record.get("record_data") if isinstance(record.get("record_data"), dict) else {}
        v = _get_path(rd, field.strip())

        op = op.strip().lower()
        if op in ("eq", "=", "equals"):
            return v == value
        if op in ("ne", "!=", "not_equals"):
            return v != value
        if op in ("gt", ">"):
            a = _coerce_num(v)
            b = _coerce_num(value)
            return a is not None and b is not None and a > b
        if op in ("gte", ">="):
            a = _coerce_num(v)
            b = _coerce_num(value)
            return a is not None and b is not None and a >= b
        if op in ("lt", "<"):
            a = _coerce_num(v)
            b = _coerce_num(value)
            return a is not None and b is not None and a < b
        if op in ("lte", "<="):
            a = _coerce_num(v)
            b = _coerce_num(value)
            return a is not None and b is not None and a <= b
        if op in ("contains",):
            if v is None:
                return False
            return str(value) in str(v)
        if op in ("starts_with", "startswith"):
            if v is None:
                return False
            return str(v).startswith(str(value))
        if op in ("ends_with", "endswith"):
            if v is None:
                return False
            return str(v).endswith(str(value))
        if op in ("in",):
            if isinstance(value, list):
                return v in value
            return False
        if op in ("exists", "is_set"):
            want = True if value is None else bool(value)
            exists = v is not None
            return exists if want else (not exists)

        return False

    # Validate inputs
    if not isinstance(search_conditions, list):
        logs = _load("xano_request_logs.json")
        _ensure_usage_log(logs, "xano_search_table_content", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
        _save("xano_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "search_conditions must be an array")

    if sort is not None:
        if not isinstance(sort, dict):
            logs = _load("xano_request_logs.json")
            _ensure_usage_log(logs, "xano_search_table_content", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
            _save("xano_request_logs.json", logs)
            return _err("VALIDATION_ERROR", "sort must be an object mapping field->('asc'|'desc')")
        for k, v in sort.items():
            if not isinstance(k, str) or not k.strip():
                logs = _load("xano_request_logs.json")
                _ensure_usage_log(logs, "xano_search_table_content", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
                _save("xano_request_logs.json", logs)
                return _err("VALIDATION_ERROR", "sort keys must be non-empty strings")
            if v not in ("asc", "desc"):
                logs = _load("xano_request_logs.json")
                _ensure_usage_log(logs, "xano_search_table_content", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
                _save("xano_request_logs.json", logs)
                return _err("VALIDATION_ERROR", "sort values must be 'asc' or 'desc'")

    if page is None:
        page = 1
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        logs = _load("xano_request_logs.json")
        _ensure_usage_log(logs, "xano_search_table_content", "VALIDATION_ERROR", (time.time() - t0) * 1000, {"instance_name": instance_name})
        _save("xano_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")

    # No per_page parameter in this tool spec; apply default 50 with same cap rules as browse
    per_page = 50

    instances = _load("xano_instances.json")
    workspaces = _load("xano_workspaces.json")
    tables = _load("xano_tables.json")
    records = _load("xano_table_records.json")
    logs = _load("xano_request_logs.json")

    inst, e = _resolve_instance(instances)
    if e:
        _ensure_usage_log(logs, "xano_search_table_content", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name})
        _save("xano_request_logs.json", logs)
        return e

    ws, e = _resolve_workspace(workspaces, inst)
    if e:
        _ensure_usage_log(logs, "xano_search_table_content", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id})
        _save("xano_request_logs.json", logs)
        return e

    tb, e = _resolve_table(tables, ws)
    if e:
        _ensure_usage_log(logs, "xano_search_table_content", e["error"]["code"], (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
        _save("xano_request_logs.json", logs)
        return e

    tb_id = tb.get("id")
    active = [r for r in records if r.get("table_id") == tb_id and r.get("status") == "active"]

    # Apply conditions: implicit AND across list
    def _matches_all(rec):
        for c in search_conditions:
            if not _match_condition(rec, c):
                return False
        return True

    matched = [r for r in active if _matches_all(r)]

    # Sorting
    if isinstance(sort, dict) and sort:
        sort_items = [(k, sort[k]) for k in sort.keys()]
        def _sort_key(rec):
            rd = rec.get("record_data") if isinstance(rec.get("record_data"), dict) else {}
            key = []
            for field, direction in sort_items:
                v = _get_path(rd, field)
                # normalize for stable sorting
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    key.append((0, float(v)))
                elif v is None:
                    key.append((2, ""))  # nulls last
                else:
                    key.append((1, str(v)))
            return tuple(key)

        # Python can't do mixed per-field directions easily; do stable sorts in reverse order
        for field, direction in reversed(sort_items):
            def _k(rec, fld=field):
                rd = rec.get("record_data") if isinstance(rec.get("record_data"), dict) else {}
                v = _get_path(rd, fld)
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    return (0, float(v))
                if v is None:
                    return (2, "")
                return (1, str(v))
            matched.sort(key=_k, reverse=(direction == "desc"))
    else:
        matched.sort(key=lambda r: str(r.get("pk_value", "")))

    total = len(matched)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = matched[start:end]
    has_more = end < total

    # Return "record_data" objects like Xano browse/search APIs commonly do, but include pk_value for traceability
    data = []
    for r in page_rows:
        data.append({
            "id": r.get("pk_value"),
            "pk_value": r.get("pk_value"),
            "record_data": r.get("record_data"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    _ensure_usage_log(logs, "xano_search_table_content", "success", (time.time() - t0) * 1000, {"instance_name": instance_name, "workspace_id": workspace_id, "table_id": table_id})
    _save("xano_request_logs.json", logs)

    return {
        "data": data,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more,
        },
        "table_id": tb.get("id"),
        "xano_table_id": tb.get("xano_table_id"),
    }

def xano_get_table_record(instance_name, workspace_id, table_id, record_id, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers ---
    def _new_id(prefix):
        # stable enough for local datastore: prefix + uuid hex
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_ulid_like(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_") and len(s) >= len(prefix) + 1 + 10

    def _coerce_positive_int(v, field_name):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a positive integer or id string")
        if isinstance(v, int):
            return (v if v > 0 else None), (None if v > 0 else _err("VALIDATION_ERROR", f"{field_name} must be a positive integer"))
        if isinstance(v, str):
            if re.fullmatch(r"\d+", v.strip() or ""):
                iv = int(v.strip())
                if iv > 0:
                    return iv, None
                return None, _err("VALIDATION_ERROR", f"{field_name} must be a positive integer")
        return None, _err("VALIDATION_ERROR", f"{field_name} must be a positive integer or id string")

    def _stringify_pk(v):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, (int, float)):
            if isinstance(v, float) and not v.is_integer():
                return None
            return str(int(v))
        if isinstance(v, str):
            s = v.strip()
            return s if s != "" else None
        return None

    def _log(status, error_code=None):
        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("xrl"),
            "endpoint": "xano_get_table_record",
            "instance_name": instance_name,
            "workspace_id": workspace_id,
            "table_id": table_id,
            "record_id": record_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("xano_request_logs.json", logs)

    # --- validation ---
    if not isinstance(instance_name, str) or not instance_name.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name must be a non-empty string")

    ws_is_local = _is_ulid_like(workspace_id, "xnw")
    tb_is_local = _is_ulid_like(table_id, "xnt")

    ws_num = None
    if not ws_is_local:
        ws_num, e = _coerce_positive_int(workspace_id, "workspace_id")
        if e:
            _log("error", e["error"]["code"])
            return e

    tb_num = None
    if not tb_is_local:
        tb_num, e = _coerce_positive_int(table_id, "table_id")
        if e:
            _log("error", e["error"]["code"])
            return e

    pk = _stringify_pk(record_id)
    if pk is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "record_id must be a non-empty string or integer")

    # --- resolve instance/workspace/table ---
    instances = _load("xano_instances.json")
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("instance_name") == instance_name and r.get("status") == "active":
            inst = r
            break
    if not inst:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Active instance not found for instance_name")

    workspaces = _load("xano_workspaces.json")
    ws = None
    for r in workspaces:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != inst.get("id"):
            continue
        if r.get("status") == "deleted":
            continue
        if ws_is_local and r.get("id") == workspace_id:
            ws = r
            break
        if (not ws_is_local) and r.get("xano_workspace_id") == ws_num:
            ws = r
            break
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for instance_name/workspace_id")

    if ws.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active")

    tables = _load("xano_tables.json")
    tbl = None
    for r in tables:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws.get("id"):
            continue
        if r.get("status") == "deleted":
            continue
        if tb_is_local and r.get("id") == table_id:
            tbl = r
            break
        if (not tb_is_local) and r.get("xano_table_id") == tb_num:
            tbl = r
            break
    if not tbl:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Table not found for workspace/table_id")

    if tbl.get("status") != "active":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Table is not active")

    records = _load("xano_table_records.json")
    rec = None
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("table_id") == tbl.get("id") and r.get("pk_value") == pk and r.get("status") == "active":
            rec = r
            break
    if not rec:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Record not found")

    _log("ok")
    # Return stored record object as stored (record_data), plus ids for traceability.
    return {
        "record": rec.get("record_data"),
        "meta": {
            "pk_field": tbl.get("pk_field_name"),
            "record_id": rec.get("pk_value"),
            "table_id": tbl.get("id"),
            "workspace_id": ws.get("id"),
            "instance_id": inst.get("id")
        }
    }

def xano_create_table_record(instance_name, workspace_id, table_id, record_data, **_extra):
    import json, os, datetime, time, uuid, re, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_ulid_like(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_") and len(s) >= len(prefix) + 1 + 10

    def _coerce_positive_int(v, field_name):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a positive integer or id string")
        if isinstance(v, int):
            return (v if v > 0 else None), (None if v > 0 else _err("VALIDATION_ERROR", f"{field_name} must be a positive integer"))
        if isinstance(v, str):
            if re.fullmatch(r"\d+", v.strip() or ""):
                iv = int(v.strip())
                if iv > 0:
                    return iv, None
                return None, _err("VALIDATION_ERROR", f"{field_name} must be a positive integer")
        return None, _err("VALIDATION_ERROR", f"{field_name} must be a positive integer or id string")

    def _stringify_pk(v):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, (int, float)):
            if isinstance(v, float) and not v.is_integer():
                return None
            return str(int(v))
        if isinstance(v, str):
            s = v.strip()
            return s if s != "" else None
        return None

    def _log(status, error_code=None):
        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("xrl"),
            "endpoint": "xano_create_table_record",
            "instance_name": instance_name,
            "workspace_id": workspace_id,
            "table_id": table_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("xano_request_logs.json", logs)

    # validation
    if not isinstance(instance_name, str) or not instance_name.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
    if not isinstance(record_data, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "record_data must be an object")

    ws_is_local = _is_ulid_like(workspace_id, "xnw")
    tb_is_local = _is_ulid_like(table_id, "xnt")

    ws_num = None
    if not ws_is_local:
        ws_num, e = _coerce_positive_int(workspace_id, "workspace_id")
        if e:
            _log("error", e["error"]["code"])
            return e

    tb_num = None
    if not tb_is_local:
        tb_num, e = _coerce_positive_int(table_id, "table_id")
        if e:
            _log("error", e["error"]["code"])
            return e

    # resolve instance/workspace/table
    instances = _load("xano_instances.json")
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("instance_name") == instance_name and r.get("status") == "active":
            inst = r
            break
    if not inst:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Active instance not found for instance_name")

    workspaces = _load("xano_workspaces.json")
    ws = None
    for r in workspaces:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != inst.get("id"):
            continue
        if r.get("status") == "deleted":
            continue
        if ws_is_local and r.get("id") == workspace_id:
            ws = r
            break
        if (not ws_is_local) and r.get("xano_workspace_id") == ws_num:
            ws = r
            break
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for instance_name/workspace_id")
    if ws.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active")

    tables = _load("xano_tables.json")
    tbl = None
    for r in tables:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws.get("id"):
            continue
        if r.get("status") == "deleted":
            continue
        if tb_is_local and r.get("id") == table_id:
            tbl = r
            break
        if (not tb_is_local) and r.get("xano_table_id") == tb_num:
            tbl = r
            break
    if not tbl:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Table not found for workspace/table_id")
    if tbl.get("status") != "active":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Table is not active")

    pk_field = tbl.get("pk_field_name")
    schema = tbl.get("schema")
    if not isinstance(pk_field, str) or not pk_field:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Table primary key configuration invalid")
    if not isinstance(schema, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Table schema snapshot missing/invalid")

    # ensure provided fields are applicable to schema (best-effort: names exist)
    # Accept if schema does not provide field list, but enforce pk field presence.
    schema_fields = None
    if isinstance(schema.get("fields"), list):
        schema_fields = []
        for f in schema.get("fields"):
            if isinstance(f, dict) and isinstance(f.get("name"), str):
                schema_fields.append(f["name"])
    if schema_fields is not None:
        for k in record_data.keys():
            if k not in schema_fields:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Field '{k}' is not in table schema")

    # determine pk_value
    provided_pk = None
    if pk_field in record_data:
        provided_pk = _stringify_pk(record_data.get(pk_field))
        if provided_pk is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Primary key field '{pk_field}' must be non-empty string/integer when provided")

    records = _load("xano_table_records.json")
    if not isinstance(records, list):
        records = []

    # allocate pk if not provided
    pk_value = provided_pk
    if pk_value is None:
        nxt = tbl.get("pk_next_value")
        if not isinstance(nxt, int) or nxt < 1:
            nxt = 1
        # find next available that doesn't collide (including deleted due to unique constraint on pk_value)
        existing_pks = set()
        for r in records:
            if isinstance(r, dict) and r.get("table_id") == tbl.get("id") and isinstance(r.get("pk_value"), str):
                existing_pks.add(r["pk_value"])
        while str(nxt) in existing_pks:
            nxt += 1
        pk_value = str(nxt)
        tbl["pk_next_value"] = nxt + 1
        tbl["updated_at"] = now
    else:
        # ensure no conflict
        for r in records:
            if isinstance(r, dict) and r.get("table_id") == tbl.get("id") and r.get("pk_value") == pk_value:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "Primary key value already exists", record_id=pk_value)

    # if client supplied pk field, must match pk_value (rule)
    if provided_pk is not None and provided_pk != pk_value:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"record_data['{pk_field}'] must match assigned pk_value")

    # prepare stored record_data with pk field set
    stored = copy.deepcopy(record_data)
    stored[pk_field] = pk_value

    new_row = {
        "id": _new_id("xnr"),
        "table_id": tbl.get("id"),
        "pk_value": pk_value,
        "record_data": stored,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # persist table pk_next_value update and record insert atomically (best-effort)
    records.append(new_row)

    # write back table update if changed
    for i, r in enumerate(tables):
        if isinstance(r, dict) and r.get("id") == tbl.get("id"):
            tables[i] = tbl
            break

    _save("xano_tables.json", tables)
    _save("xano_table_records.json", records)

    _log("ok")
    return {
        "record": new_row.get("record_data"),
        "meta": {
            "pk_field": pk_field,
            "record_id": pk_value,
            "table_id": tbl.get("id"),
            "workspace_id": ws.get("id"),
            "instance_id": inst.get("id")
        }
    }

