def xano_bulk_create_records(instance_name, workspace_id, table_id, records, allow_id_field=None, **_extra):
    import json, os, datetime, time, uuid, re, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_bulk_create_records"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error=None, **ctx):
        logs = _ensure_logs()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "context": ctx or {}
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, float):
            if v.is_integer() and int(v) > 0:
                return int(v), None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)

    def _is_ulid_prefix(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_")

    def _gen_id(prefix):
        return f"{prefix}_" + uuid.uuid4().hex[:26]

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    if not isinstance(records, list) or len(records) < 1:
        e = _err("VALIDATION_ERROR", "records must be a non-empty array.", field="records")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    for r in records:
        if not isinstance(r, dict):
            e = _err("VALIDATION_ERROR", "Each record must be an object.", field="records")
            _log("error", error=e["error"], instance_name=instance_name)
            return e
    if allow_id_field is None:
        allow_id_field = False
    if not isinstance(allow_id_field, bool):
        e = _err("VALIDATION_ERROR", "allow_id_field must be a boolean.", field="allow_id_field")
        _log("error", error=e["error"], instance_name=instance_name)
        return e

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    tables = _load("xano_tables.json")
    if not isinstance(tables, list):
        tables = []
    table_records = _load("xano_table_records.json")
    if not isinstance(table_records, list):
        table_records = []

    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    ws_row = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted"), None)
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    table_row = None
    if _is_ulid_prefix(table_id, "xnt"):
        table_row = next((t for t in tables if t.get("id") == table_id and t.get("workspace_id") == ws_row.get("id") and t.get("status") != "deleted"), None)
    else:
        tid_num, terr = _as_positive_int(table_id, "table_id")
        if terr:
            _log("error", error=terr["error"], instance_name=instance_name, table_id=table_id)
            return terr
        table_row = next((t for t in tables if t.get("workspace_id") == ws_row.get("id") and t.get("xano_table_id") == tid_num and t.get("status") != "deleted"), None)
    if not table_row:
        e = _err("NOT_FOUND", "Table not found.", field="table_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, table_id=table_id)
        return e

    pk_name = table_row.get("pk_field_name") or "id"
    existing_pk = set()
    for r in table_records:
        if r.get("table_id") == table_row.get("id"):
            pv = r.get("pk_value")
            if isinstance(pv, str):
                existing_pk.add(pv)

    # Validate batch uniqueness + against existing
    planned = []
    batch_pk = set()
    next_int = table_row.get("pk_next_value")
    if not isinstance(next_int, int) or next_int < 1:
        next_int = 1

    # Pre-check any unique indexes (btree unique) or search indexes don't matter; enforce only unique indexes
    unique_indexes = []
    if isinstance(table_row.get("indexes"), list):
        for idx in table_row["indexes"]:
            if isinstance(idx, dict) and idx.get("type") == "unique" and idx.get("status") == "active":
                unique_indexes.append(idx)

    def _check_unique_indexes(candidate_records):
        # candidate_records: list of record_data dicts
        if not unique_indexes:
            return None
        # Build existing values for each unique index key
        active_existing = [r for r in table_records if r.get("table_id") == table_row.get("id") and r.get("status") == "active"]
        existing_data = [r.get("record_data") for r in active_existing if isinstance(r.get("record_data"), dict)]
        for idx in unique_indexes:
            fields_spec = idx.get("fields")
            if not isinstance(fields_spec, list) or not fields_spec:
                continue
            fnames = [f.get("name") for f in fields_spec if isinstance(f, dict) and isinstance(f.get("name"), str)]
            fnames = [n for n in fnames if n]
            if not fnames:
                continue
            seen = set()
            for d in existing_data:
                key = tuple(d.get(n) for n in fnames)
                seen.add(key)
            # check candidates don't collide existing and among themselves
            for d in candidate_records:
                key = tuple(d.get(n) for n in fnames)
                if key in seen:
                    return _err("CONFLICT", f"Unique index violation on fields {fnames}.", index_id=idx.get("index_id"))
                seen.add(key)
        return None

    # Build planned inserts
    for rec in records:
        rec_in = copy.deepcopy(rec)
        if not allow_id_field and pk_name in rec_in:
            e = _err("VALIDATION_ERROR", f"Primary key field '{pk_name}' cannot be set when allow_id_field=false.", field="records")
            _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
            return e

        if allow_id_field and pk_name in rec_in:
            pkv_raw = rec_in.get(pk_name)
            if pkv_raw is None or (isinstance(pkv_raw, str) and pkv_raw == ""):
                e = _err("VALIDATION_ERROR", f"Primary key field '{pk_name}' cannot be empty.", field="records")
                _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
                return e
            # accept string/number
            if isinstance(pkv_raw, (int, float)) and not isinstance(pkv_raw, bool):
                if isinstance(pkv_raw, float) and not pkv_raw.is_integer():
                    e = _err("VALIDATION_ERROR", f"Primary key field '{pk_name}' must be an integer or string.", field="records")
                    _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
                    return e
                pkv = str(int(pkv_raw))
            else:
                pkv = str(pkv_raw)
            if pkv in existing_pk:
                e = _err("CONFLICT", "Primary key already exists.", pk_value=pkv)
                _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
                return e
            if pkv in batch_pk:
                e = _err("CONFLICT", "Duplicate primary key within the batch.", pk_value=pkv)
                _log("error", error=e["error"], instance_name=instance_name, table_id=table_id)
                return e
            batch_pk.add(pkv)
        else:
            # assign
            pkv = str(next_int)
            next_int += 1
            # ensure not conflicting; if conflicts, keep incrementing
            while pkv in existing_pk or pkv in batch_pk:
                pkv = str(next_int)
                next_int += 1
            batch_pk.add(pkv)
            rec_in[pk_name] = int(pkv) if re.fullmatch(r"[0-9]+", pkv) else pkv

        planned.append((pkv, rec_in))

    # Enforce unique indexes against final candidate record_data
    uerr = _check_unique_indexes([p[1] for p in planned])
    if uerr:
        _log("error", error=uerr["error"], instance_name=instance_name, table_id=table_id)
        return uerr

    # Apply atomically: only now mutate store
    now = _now()
    created = []
    for pkv, recdata in planned:
        row = {
            "id": _gen_id("xnr"),
            "table_id": table_row.get("id"),
            "pk_value": str(pkv),
            "record_data": recdata,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        table_records.append(row)
        created.append(recdata)

    # update pk_next_value if we auto-assigned values
    if not allow_id_field:
        # find table index
        tlist = tables
        for i, t in enumerate(tlist):
            if t.get("id") == table_row.get("id"):
                tlist[i]["pk_next_value"] = next_int
                tlist[i]["updated_at"] = now
                break
        _save("xano_tables.json", tlist)

    _save("xano_table_records.json", table_records)
    _log("ok", instance_name=instance_name, workspace_id=workspace_id, table_id=table_id, count=len(created))
    return {"data": created, "meta": {"created": len(created)}}

def xano_bulk_update_records(instance_name, workspace_id, table_id, updates, **_extra):
    import json, os, datetime, time, uuid, re, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
