        e = _err("VALIDATION_ERROR", "record_ids must be a non-empty array.", field="record_ids")
        _log("error", error=e["error"], instance_name=instance_name)
        return e

    parsed_ids = []
    for rid in record_ids:
        if isinstance(rid, bool) or rid is None:
            e = _err("VALIDATION_ERROR", "record_ids items must be strings or numbers.", field="record_ids")
            _log("error", error=e["error"], instance_name=instance_name)
            return e
        if isinstance(rid, (int, float)) and not isinstance(rid, bool):
            if isinstance(rid, float) and not rid.is_integer():
                e = _err("VALIDATION_ERROR", "record_ids numeric values must be integers.", field="record_ids")
                _log("error", error=e["error"], instance_name=instance_name)
                return e
            parsed_ids.append(str(int(rid)))
        else:
            parsed_ids.append(str(rid))

    instances = _load("xano_instances.json")
