        table_records[i]["updated_at"] = now
        deleted += 1
        results.append({"record_id": pkv, "status": "deleted"})

    if deleted == 0 and not_found == len(parsed_ids):
        # nothing affected at all (all missing) => NOT_FOUND
        e = _err("NOT_FOUND", "No records found for deletion.", field="record_ids")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, table_id=table_id)
        return e

    _save("xano_table_records.json", table_records)
    _log("ok", instance_name=instance_name, workspace_id=workspace_id, table_id=table_id, deleted=deleted, not_found=not_found)
    return {"data": results, "meta": {"deleted": deleted, "not_found": not_found}}

def xano_truncate_table(instance_name, workspace_id, table_id, reset=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        t = int(time.time() * 1000)
        return f"{prefix}{t:x}{os.urandom(6).hex()}"

    def _to_pos_int(v):
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v if v > 0 else None
        if isinstance(v, float):
            if v.is_integer():
                iv = int(v)
                return iv if iv > 0 else None
            return None
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                iv = int(s)
                return iv if iv > 0 else None
            return None
        return None

    def _resolve_instance(instances, name):
        if not isinstance(name, str) or not name.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        matches = [r for r in instances if r.get("instance_name") == name]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found", instance_name=name)
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) != 1:
            return None, _err("NOT_FOUND", "Instance is not active", instance_name=name)
        return active[0], None

    def _resolve_workspace(workspaces, instance_row, ws_param):
        if isinstance(ws_param, str) and re.fullmatch(r"^xnw_[0-9A-HJKMNP-TV-Z]{16,}$", ws_param or ""):
            w = next((r for r in workspaces if r.get("id") == ws_param and r.get("instance_id") == instance_row.get("id") and r.get("status") != "deleted"), None)
            if not w:
                return None, _err("NOT_FOUND", "Workspace not found", workspace_id=ws_param)
            return w, None
        ws_num = _to_pos_int(ws_param)
        if ws_num is None:
            return None, _err("VALIDATION_ERROR", "workspace_id must be a workspace ULID string or a positive integer", workspace_id=ws_param)
        w = next((r for r in workspaces if r.get("instance_id") == instance_row.get("id") and r.get("xano_workspace_id") == ws_num and r.get("status") != "deleted"), None)
        if not w:
            return None, _err("NOT_FOUND", "Workspace not found", workspace_id=ws_param)
        return w, None

    def _resolve_table(tables, workspace_row, tbl_param):
        if isinstance(tbl_param, str) and re.fullmatch(r"^xnt_[0-9A-HJKMNP-TV-Z]{16,}$", tbl_param or ""):
            trow = next((r for r in tables if r.get("id") == tbl_param and r.get("workspace_id") == workspace_row.get("id") and r.get("status") != "deleted"), None)
            if not trow:
                return None, _err("NOT_FOUND", "Table not found", table_id=tbl_param)
            return trow, None
        tbl_num = _to_pos_int(tbl_param)
        if tbl_num is None:
            return None, _err("VALIDATION_ERROR", "table_id must be a table ULID string or a positive integer", table_id=tbl_param)
        trow = next((r for r in tables if r.get("workspace_id") == workspace_row.get("id") and r.get("xano_table_id") == tbl_num and r.get("status") != "deleted"), None)
        if not trow:
            return None, _err("NOT_FOUND", "Table not found", table_id=tbl_param)
        return trow, None

    def _log_call(endpoint, status, latency_ms, meta=None):
        candidates = ["request_logs.json", "usage_logs.json", "api_request_logs.json", "audit_logs.json"]
        log_file = next((c for c in candidates if os.path.exists(os.path.join(_DB, c))), None)
        if not log_file:
            return
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("log_"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save(log_file, logs)

    t0 = time.time()
    endpoint = "xano_truncate_table"

    if reset is None:
        reset = False
    if not isinstance(reset, bool):
        latency = int((time.time() - t0) * 1000)
        _log_call(endpoint, "error", latency, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "reset must be a boolean if provided")

    instances = _load("xano_instances.json")
    workspaces = _load("xano_workspaces.json")
    tables = _load("xano_tables.json")
    table_records = _load("xano_table_records.json")

    inst, e = _resolve_instance(instances, instance_name)
    if e:
        latency = int((time.time() - t0) * 1000)
        _log_call(endpoint, "error", latency, {"code": e["error"]["code"]})
        return e

    ws, e = _resolve_workspace(workspaces, inst, workspace_id)
    if e:
        latency = int((time.time() - t0) * 1000)
        _log_call(endpoint, "error", latency, {"code": e["error"]["code"]})
        return e

    tbl, e = _resolve_table(tables, ws, table_id)
    if e:
        latency = int((time.time() - t0) * 1000)
        _log_call(endpoint, "error", latency, {"code": e["error"]["code"]})
        return e

    if tbl.get("status") != "active":
        latency = int((time.time() - t0) * 1000)
        _log_call(endpoint, "error", latency, {"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", "Table is not active", table_status=tbl.get("status"))

    # Truncate: mark all records for this table deleted (including already deleted remain deleted)
    now = _now_iso()
    affected = 0
    for idx, r in enumerate(table_records):
        if r.get("table_id") == tbl.get("id") and r.get("status") != "deleted":
            r["status"] = "deleted"
            r["updated_at"] = now
            table_records[idx] = r
            affected += 1

    if affected == 0:
        # "no success without effect" - truncating an already-empty table should be NOT_FOUND? In real APIs it succeeds.
        # Here, treat it as effectful if there are any rows (even deleted) maybe none; but rule says no success w/o effect.
        # We'll consider effect if reset changes pk counter, otherwise NOT_FOUND.
        if not reset:
            latency = int((time.time() - t0) * 1000)
            _log_call(endpoint, "error", latency, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "No active records to truncate")
    _save("xano_table_records.json", table_records)

    # Reset pk counter if requested
    pk_reset_done = False
    if reset:
        tbl["pk_next_value"] = 1
        pk_reset_done = True
        tbl["updated_at"] = now
        for i, tr in enumerate(tables):
            if tr.get("id") == tbl.get("id"):
                tables[i] = tbl
                break
        _save("xano_tables.json", tables)

    inst["last_discovered_at"] = now
    inst["updated_at"] = inst.get("updated_at") or now
    for idx, ir in enumerate(instances):
        if ir.get("id") == inst.get("id"):
            instances[idx] = inst
            break
    _save("xano_instances.json", instances)

    latency = int((time.time() - t0) * 1000)
    _log_call(endpoint, "ok", latency, {"truncated": affected, "pk_reset": pk_reset_done})

    return {
        "data": {
            "table_id": tbl.get("id"),
            "truncated": affected,
            "pk_reset": pk_reset_done
        },
        "meta": {"truncated": affected, "pk_reset": pk_reset_done}
    }

def xano_list_files(instance_name, workspace_id, page=None, per_page=None, search=None, access=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "xano_list_files",
            "status": status,
            "error_code": error_code,
            "instance_name": instance_name,
            "workspace_id": workspace_id,
            "timestamp": req_ts,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rate, int) and rate > 0:
            cutoff = (now - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota > 0:
            day_prefix = now.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts.startswith(day_prefix):
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    limit_err = _check_limits()
    if limit_err:
        _append_request_log("error", limit_err["error"]["code"])
        return limit_err

    try:
        if not isinstance(instance_name, str) or not instance_name.strip():
            raise ValueError("instance_name")
        if page is None:
            page = 1
        if per_page is None:
            per_page = 50
        if not isinstance(page, int) or page < 1:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
        if not isinstance(per_page, int) or per_page < 1 or per_page > 200:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 200.")
        if search is not None and (not isinstance(search, str)):
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "search must be a string.")
        if access is not None and access not in ("public", "private"):
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "access must be one of: public, private.")
        if sort is None:
            sort = "created_at"
        if sort not in ("created_at", "name"):
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort must be one of: created_at, name.")
        if sort_direction is None:
            sort_direction = "desc"
        if sort_direction not in ("asc", "desc"):
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_direction must be one of: asc, desc.")
    except ValueError:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name is required and must be a non-empty string.")

    instances = _load("xano_instances.json")
    inst = None
    for r in instances:
        if r.get("instance_name") == instance_name and r.get("status") == "active":
            inst = r
            break
    if not inst:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Active instance not found for instance_name.")

    workspaces = _load("xano_workspaces.json")
    ws = None
    ulid_re = re.compile(r"^xnw_[0-9A-HJKMNP-TV-Z]{16,}$")
    if isinstance(workspace_id, str) and ulid_re.match(workspace_id):
        for w in workspaces:
            if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted":
                ws = w
                break
    else:
        try:
            wid = int(workspace_id)
        except Exception:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must be a workspace ULID string or a positive integer.")
        if wid <= 0:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must be a positive integer.")
        for w in workspaces:
            if w.get("instance_id") == inst.get("id") and w.get("status") != "deleted" and int(w.get("xano_workspace_id", -1)) == wid:
                ws = w
                break
    if not ws:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for this instance.")

    artifacts = _load("xano_workspace_artifacts.json")
    rows = []
    term = (search or "").strip().lower() if isinstance(search, str) else ""
    for a in artifacts:
        if a.get("workspace_id") != ws.get("id"):
            continue
        if a.get("artifact_type") != "file":
            continue
        if a.get("status") != "active":
            continue
        if access is not None and a.get("access") != access:
            continue
        if term:
            hay = " ".join([str(a.get("name") or ""), str(a.get("description") or ""), str(a.get("content_type") or "")]).lower()
            if term not in hay:
                continue
        rows.append(a)

    def _key(v):
        if sort == "name":
            return (str(v.get("name") or "").lower(), str(v.get("id") or ""))
        return (str(v.get("created_at") or ""), str(v.get("id") or ""))

    rows.sort(key=_key, reverse=(sort_direction == "desc"))

    total = len(rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end] if start < total else []
    has_more = end < total

    _append_request_log("ok", None)
    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more
        }
    }

