        return limit_err

    if not isinstance(instance_name, str) or not instance_name.strip():
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name is required and must be a non-empty string.")

    instances = _load("xano_instances.json")
    inst = None
    for r in instances:
        if r.get("instance_name") == instance_name and r.get("status") == "active":
            inst = r
            break
    if not inst:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Active instance not found for instance_name.")

    workspaces = _load("xano_workspaces.json")
    ws = None
    ws_ulid_re = re.compile(r"^xnw_[0-9A-HJKMNP-TV-Z]{16,}$")
    if isinstance(workspace_id, str) and ws_ulid_re.match(workspace_id):
        for w in workspaces:
            if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted":
                ws = w
                break
    else:
        try:
            wid = int(workspace_id)
        except Exception:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must be a workspace ULID string or a positive integer.")
        if wid <= 0:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must be a positive integer.")
        for w in workspaces:
            if w.get("instance_id") == inst.get("id") and w.get("status") != "deleted" and int(w.get("xano_workspace_id", -1)) == wid:
                ws = w
                break
    if not ws:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for this instance.")

    artifacts = _load("xano_workspace_artifacts.json")

    target_idx = None
    target = None
    art_ulid_re = re.compile(r"^xna_[0-9A-HJKMNP-TV-Z]{16,}$")
    if isinstance(file_id, str) and art_ulid_re.match(file_id):
        for i, a in enumerate(artifacts):
            if a.get("id") == file_id and a.get("workspace_id") == ws.get("id") and a.get("artifact_type") == "file":
                target_idx = i
                target = a
                break
    else:
        try:
            fid = int(file_id)
        except Exception:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "file_id must be a file ULID string or a positive integer.")
        if fid <= 0:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "file_id must be a positive integer.")
        for i, a in enumerate(artifacts):
            if a.get("workspace_id") == ws.get("id") and a.get("artifact_type") == "file" and a.get("xano_object_id") is not None:
                try:
                    if int(a.get("xano_object_id")) == fid:
                        target_idx = i
                        target = a
                        break
                except Exception:
                    continue

    if target is None:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "File not found in this workspace.")

    if target.get("status") == "deleted":
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "File not found (already deleted).")

    # Transition to deleted (active -> deleted). Other statuses are invalid for file here.
    if target.get("status") not in ("active", "processing", "failed"):
        _append_request_log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "File cannot be deleted from its current status.", current_status=target.get("status"))

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    target = dict(target)
    target["status"] = "deleted"
    target["updated_at"] = now
    artifacts[target_idx] = target
    _save("xano_workspace_artifacts.json", artifacts)

    _append_request_log("ok", None)
    return {"data": target}

def xano_bulk_delete_files(instance_name, workspace_id, file_ids, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_bulk_delete_files"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error=None, **ctx):
        logs = _ensure_logs()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "context": ctx or {}
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)

    def _is_ulid_prefix(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_")

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    if not isinstance(file_ids, list) or len(file_ids) < 1:
        e = _err("VALIDATION_ERROR", "file_ids must be a non-empty array.", field="file_ids")
        _log("error", error=e["error"], instance_name=instance_name)
        return e

    parsed = []
    for fid in file_ids:
        if isinstance(fid, bool) or fid is None:
            e = _err("VALIDATION_ERROR", "file_ids items must be strings or integers.", field="file_ids")
            _log("error", error=e["error"], instance_name=instance_name)
            return e
        if isinstance(fid, int):
            if fid <= 0:
                e = _err("VALIDATION_ERROR", "Numeric file_ids must be positive integers.", field="file_ids")
                _log("error", error=e["error"], instance_name=instance_name)
                return e
            parsed.append(("num", fid))
        elif isinstance(fid, str):
            s = fid.strip()
            if _is_ulid_prefix(s, "xna"):
                parsed.append(("id", s))
            elif re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n <= 0:
                    e = _err("VALIDATION_ERROR", "Numeric file_ids must be positive integers.", field="file_ids")
                    _log("error", error=e["error"], instance_name=instance_name)
                    return e
                parsed.append(("num", n))
            else:
                e = _err("VALIDATION_ERROR", "Invalid file id.", field="file_ids")
                _log("error", error=e["error"], instance_name=instance_name)
                return e
        else:
            e = _err("VALIDATION_ERROR", "file_ids items must be strings or integers.", field="file_ids")
            _log("error", error=e["error"], instance_name=instance_name)
            return e

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    artifacts = _load("xano_workspace_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    ws_row = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted"), None)
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    # Index artifacts
    by_ulid = {}
    by_num = {}
    for i, a in enumerate(artifacts):
        if a.get("workspace_id") != ws_row.get("id"):
            continue
        if a.get("artifact_type") != "file":
            continue
        aid = a.get("id")
        if isinstance(aid, str):
            by_ulid[aid] = i
        xo = a.get("xano_object_id")
        if isinstance(xo, int):
            by_num[xo] = i

    now = _now()
    results = []
    deleted = 0
    not_found = 0

    for kind, val in parsed:
        idx = by_ulid.get(val) if kind == "id" else by_num.get(val)
        if idx is None:
            not_found += 1
            results.append({"file_id": val, "status": "not_found"})
            continue
        if artifacts[idx].get("status") == "deleted":
            results.append({"file_id": artifacts[idx].get("id") or val, "status": "already_deleted"})
            continue
        artifacts[idx]["status"] = "deleted"
        artifacts[idx]["updated_at"] = now
        deleted += 1
        results.append({"file_id": artifacts[idx].get("id") or val, "status": "deleted"})

    if deleted == 0 and not_found == len(parsed):
        e = _err("NOT_FOUND", "No files found for deletion.", field="file_ids")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    _save("xano_workspace_artifacts.json", artifacts)
    _log("ok", instance_name=instance_name, workspace_id=workspace_id, deleted=deleted, not_found=not_found)
    return {"data": results, "meta": {"deleted": deleted, "not_found": not_found}}

def xano_browse_request_history(instance_name, workspace_id, page=None, per_page=None, branch=None, api_id=None, query_id=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_ulidish(s):
        if not isinstance(s, str):
            return False
        if len(s) < 10 or len(s) > 40:
            return False
        allowed = "0123456789ABCDEFGHJKMNPQRSTVWXYZabcdefghijklmnopqrstuvwxyz_-"
        return all(c in allowed for c in s)

    def _parse_pos_int_or_ulid(v, field):
        if v is None:
            return None, None
        if isinstance(v, int):
            if v <= 0:
                return _err("VALIDATION_ERROR", f"{field} must be a positive integer", field=field), None
            return ("int", v), None
        if isinstance(v, str):
            s = v.strip()
            if s == "":
                return _err("VALIDATION_ERROR", f"{field} is required", field=field), None
            if s.isdigit():
                iv = int(s)
                if iv <= 0:
                    return _err("VALIDATION_ERROR", f"{field} must be a positive integer", field=field), None
                return ("int", iv), None
            if _is_ulidish(s):
                return ("ulid", s), None
            return _err("VALIDATION_ERROR", f"{field} must be a positive integer id or a valid identifier", field=field), None
        return _err("VALIDATION_ERROR", f"{field} must be a string or integer", field=field), None

    def _audit(endpoint, status, instance_row_id=None, workspace_row_id=None, extra=None):
        logs = _load("xano_workspace_artifacts.json")
        # Store audit as request_history artifact in the same artifacts collection, with xano_object_id=None
        entry = {
            "id": "reqlog_" + uuid.uuid4().hex,
            "workspace_id": workspace_row_id or "",
            "artifact_type": "request_history",
            "branch": (extra or {}).get("branch"),
            "xano_object_id": None,
            "parent_artifact_id": None,
            "name": endpoint,
            "description": None,
            "docs": None,
            "swagger_enabled": None,
            "guid": None,
            "canonical_url": None,
            "access": None,
            "size_bytes": None,
            "content_type": None,
            "download_url": None,
            "password_protected": None,
            "payload": {
                "mcp_audit": True,
                "endpoint": endpoint,
                "status": status,
                "instance_id": instance_row_id,
                "workspace_id": workspace_row_id,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now_iso(),
            },
            "status": "active",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        if extra:
            entry["payload"].update(extra)
        logs.append(entry)
        _save("xano_workspace_artifacts.json", logs)

    # Validate required basics
    if not isinstance(instance_name, str) or not instance_name.strip():
        _audit("xano_browse_request_history", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "instance_name must be a non-empty string", field="instance_name")

    if page is None:
        page = 1
    if per_page is None:
        per_page = 50

    if not isinstance(page, int) or page < 1:
        _audit("xano_browse_request_history", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 200:
        _audit("xano_browse_request_history", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 200", field="per_page")

    if branch is not None:
        if not isinstance(branch, str) or not branch.strip() or len(branch) > 64:
            _audit("xano_browse_request_history", "error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "branch must be a non-empty string up to 64 characters", field="branch")
        branch = branch.strip()

    ws_key, e = _parse_pos_int_or_ulid(workspace_id, "workspace_id")
    if e:
        _audit("xano_browse_request_history", "error", extra={"error_code": e["error"]["code"]})
        return e

    api_key, e = _parse_pos_int_or_ulid(api_id, "api_id")
    if e:
        _audit("xano_browse_request_history", "error", extra={"error_code": e["error"]["code"]})
        return e
    query_key, e = _parse_pos_int_or_ulid(query_id, "query_id")
    if e:
        _audit("xano_browse_request_history", "error", extra={"error_code": e["error"]["code"]})
        return e

    instances = _load("xano_instances.json")
    inst = None
    for r in instances:
        if r.get("instance_name") == instance_name and r.get("status") == "active":
            inst = r
            break
    if not inst:
        _audit("xano_browse_request_history", "error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Active instance not found for instance_name", field="instance_name")

    workspaces = _load("xano_workspaces.json")
    ws = None
    if ws_key[0] == "ulid":
        for r in workspaces:
            if r.get("id") == ws_key[1] and r.get("instance_id") == inst.get("id") and r.get("status") != "deleted":
                ws = r
                break
    else:
        for r in workspaces:
            if r.get("instance_id") == inst.get("id") and r.get("xano_workspace_id") == ws_key[1] and r.get("status") != "deleted":
                ws = r
                break

    if not ws:
        _audit("xano_browse_request_history", "error", inst.get("id"), None, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found", field="workspace_id")

    artifacts = _load("xano_workspace_artifacts.json")
    rows = []
    for a in artifacts:
        if a.get("workspace_id") != ws.get("id"):
            continue
        if a.get("artifact_type") != "request_history":
            continue
        if a.get("status") == "deleted":
            continue
        if branch is not None and a.get("branch") != branch:
            continue

        if api_key is not None:
            p = a.get("payload") if isinstance(a.get("payload"), dict) else {}
            if api_key[0] == "ulid":
                if p.get("api_artifact_id") != api_key[1] and p.get("api_id") != api_key[1]:
                    continue
            else:
                if p.get("api_id") != api_key[1]:
                    continue

        if query_key is not None:
            p = a.get("payload") if isinstance(a.get("payload"), dict) else {}
            if query_key[0] == "ulid":
                if p.get("query_artifact_id") != query_key[1] and p.get("query_id") != query_key[1]:
                    continue
            else:
                if p.get("query_id") != query_key[1]:
                    continue

        rows.append(a)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min, r.get("id") or ""), reverse=True)

    total = len(rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end]
    has_more = end < total

    _audit(
        "xano_browse_request_history",
        "ok",
        inst.get("id"),
        ws.get("id"),
        extra={"branch": branch, "page": page, "per_page": per_page, "result_count": len(page_rows)},
    )

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more,
        },
    }

