    if page is None:
        page = 1
    if per_page is None:
        per_page = 50
    if not isinstance(page, int) or page < 1:
        _audit("xano_browse_api_groups", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
