    if search is not None and (not isinstance(search, str) or len(search) > 200):
        _audit("xano_browse_api_groups", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "search must be a string up to 200 characters", field="search")

    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    if sort not in ("created_at", "updated_at", "name"):
        _audit("xano_browse_api_groups", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name", field="sort")
    if order not in ("asc", "desc"):
        _audit("xano_browse_api_groups", "error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc", field="order")

    instances = _load("xano_instances.json")
    inst = None
    for r in instances:
        if r.get("instance_name") == instance_name and r.get("status") == "active":
            inst = r
            break
    if not inst:
        _audit("xano_browse_api_groups", "error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Active instance not found for instance_name", field="instance_name")

    workspaces = _load("xano_workspaces.json")
    ws = None
    if ws_key[0] == "ulid":
        for r in workspaces:
            if r.get("id") == ws_key[1] and r.get("instance_id") == inst.get("id") and r.get("status") != "deleted":
                ws = r
                break
    else:
        for r in workspaces:
            if r.get("instance_id") == inst.get("id") and r.get("xano_workspace_id") == ws_key[1] and r.get("status") != "deleted":
                ws = r
                break
    if not ws:
        _audit("xano_browse_api_groups", "error", inst.get("id"), None, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found", field="workspace_id")

    artifacts = _load("xano_workspace_artifacts.json")
    groups = []
    q = (search or "").strip().lower()
    for a in artifacts:
        if a.get("workspace_id") != ws.get("id"):
            continue
        if a.get("artifact_type") != "api_group":
            continue
        if a.get("status") == "deleted":
            continue
        if branch is not None and a.get("branch") != branch:
            continue
        if q:
            nm = (a.get("name") or "").lower()
            desc = (a.get("description") or "").lower()
            docs = (a.get("docs") or "").lower()
            if q not in nm and q not in desc and q not in docs:
                continue
        groups.append(a)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    reverse = (order == "desc")
    if sort in ("created_at", "updated_at"):
        groups.sort(key=lambda r: (_parse_dt(r.get(sort)) or datetime.datetime.min, r.get("id") or ""), reverse=reverse)
    else:
        groups.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("id") or ""), reverse=reverse)

    total = len(groups)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = groups[start:end]
    has_more = end < total

    _audit(
        "xano_browse_api_groups",
        "ok",
        inst.get("id"),
        ws.get("id"),
        extra={"branch": branch, "page": page, "per_page": per_page, "sort": sort, "order": order, "result_count": len(page_rows)},
    )

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more,
        },
    }

def xano_get_api_group(instance_name, workspace_id, apigroup_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _as_pos_int(v, field):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer or string id")
        if isinstance(v, int):
            return (v if v > 0 else None), (None if v > 0 else _err("VALIDATION_ERROR", f"{field} must be a positive integer"))
        if isinstance(v, str):
            s = v.strip()
            if s.isdigit():
                iv = int(s)
                if iv <= 0:
                    return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
                return iv, None
            return None, None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer or string id")

    def _is_str(v):
        return isinstance(v, str) and v.strip() != ""

    def _get_instance(instances, name):
        if not _is_str(name):
            return None, _err("VALIDATION_ERROR", "instance_name is required")
        matches = [r for r in instances if r.get("instance_name") == name]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found")
        active = [r for r in matches if r.get("status") == "active"]
        if not active:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance not active (status={st})")
        if len(active) != 1:
            return None, _err("CONFLICT", "Multiple active instances match instance_name")
        return active[0], None

    def _resolve_workspace(workspaces, instance_row, workspace_id_value):
        if isinstance(workspace_id_value, str) and workspace_id_value.strip() != "" and not workspace_id_value.strip().isdigit():
            wid = workspace_id_value.strip()
            ws = next((w for w in workspaces if w.get("id") == wid), None)
            if not ws:
                return None, _err("NOT_FOUND", "Workspace not found")
            if ws.get("instance_id") != instance_row.get("id"):
                return None, _err("NOT_FOUND", "Workspace not in instance")
            if ws.get("status") == "deleted":
                return None, _err("NOT_FOUND", "Workspace deleted")
