    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _as_pos_int(v, field):
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer or string id")
        if isinstance(v, int):
            return (v if v > 0 else None), (None if v > 0 else _err("VALIDATION_ERROR", f"{field} must be a positive integer"))
        if isinstance(v, str):
            s = v.strip()
            if s.isdigit():
                iv = int(s)
                if iv <= 0:
                    return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
                return iv, None
            return None, None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer or string id")

    def _is_str(v):
        return isinstance(v, str) and v.strip() != ""

    def _get_instance(instances, name_):
        if not _is_str(name_):
            return None, _err("VALIDATION_ERROR", "instance_name is required")
        matches = [r for r in instances if r.get("instance_name") == name_]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found")
        active = [r for r in matches if r.get("status") == "active"]
        if not active:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance not active (status={st})")
        if len(active) != 1:
            return None, _err("CONFLICT", "Multiple active instances match instance_name")
        return active[0], None

    def _resolve_workspace(workspaces, instance_row, workspace_id_value):
        if isinstance(workspace_id_value, str) and workspace_id_value.strip() != "" and not workspace_id_value.strip().isdigit():
            wid = workspace_id_value.strip()
            ws = next((w for w in workspaces if w.get("id") == wid), None)
            if not ws:
                return None, _err("NOT_FOUND", "Workspace not found")
            if ws.get("instance_id") != instance_row.get("id"):
                return None, _err("NOT_FOUND", "Workspace not in instance")
            if ws.get("status") == "deleted":
                return None, _err("NOT_FOUND", "Workspace deleted")
            if ws.get("status") != "active":
                return None, _err("UNAUTHORIZED", f"Workspace not accessible (status={ws.get('status')})")
            return ws, None

        n, e = _as_pos_int(workspace_id_value, "workspace_id")
        if e:
            return None, e
        if n is None:
            return None, _err("VALIDATION_ERROR", "workspace_id is required")
        ws = next((w for w in workspaces if w.get("instance_id") == instance_row.get("id") and int(w.get("xano_workspace_id", -1)) == n), None)
        if not ws:
            return None, _err("NOT_FOUND", "Workspace not found")
        if ws.get("status") == "deleted":
            return None, _err("NOT_FOUND", "Workspace deleted")
        if ws.get("status") != "active":
            return None, _err("UNAUTHORIZED", f"Workspace not accessible (status={ws.get('status')})")
        return ws, None

    def _ensure_audit(endpoint, status, latency_ms, instance_id=None, workspace_id_val=None, artifact_id=None):
        audit = _load("xano_audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({
            "id": "aud_" + uuid.uuid4().hex,
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "instance_id": instance_id,
            "workspace_id": workspace_id_val,
            "artifact_id": artifact_id,
        })
        _save("xano_audit_log.json", audit)

    t0 = time.time()
    endpoint = "xano_create_api_group"

    try:
        if not _is_str(name):
            _ensure_audit(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "name is required")

        if description is not None and not isinstance(description, str):
            _ensure_audit(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "description must be a string")
        if docs is not None and not isinstance(docs, str):
            _ensure_audit(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "docs must be a string")
        if branch is not None and not isinstance(branch, str):
            _ensure_audit(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "branch must be a string")
        if swagger is not None and not isinstance(swagger, bool):
            _ensure_audit(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "swagger must be a boolean")

        instances = _load("xano_instances.json")
        workspaces = _load("xano_workspaces.json")
        artifacts = _load("xano_workspace_artifacts.json")

