            _ensure_audit(endpoint, err["error"]["code"], (time.time() - t0) * 1000.0)
            return err

        ws, err = _resolve_workspace(workspaces, inst, workspace_id)
        if err:
            _ensure_audit(endpoint, err["error"]["code"], (time.time() - t0) * 1000.0, instance_id=inst.get("id"))
            return err

        eff_branch = branch if _is_str(branch) else ws.get("branch_default")
        if not _is_str(eff_branch):
            _ensure_audit(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000.0, instance_id=inst.get("id"), workspace_id_val=ws.get("id"))
            return _err("VALIDATION_ERROR", "branch is required (no branch provided and workspace has no branch_default)")

        # Determine next xano_object_id within workspace for api_group artifacts
        existing = [a for a in artifacts if a.get("workspace_id") == ws.get("id") and a.get("artifact_type") == "api_group" and a.get("status") != "deleted" and isinstance(a.get("xano_object_id"), int)]
        next_oid = (max([a["xano_object_id"] for a in existing], default=0) + 1)

        new_id = "ag_" + uuid.uuid4().hex
        now = _now()
        row = {
            "id": new_id,
            "workspace_id": ws.get("id"),
            "artifact_type": "api_group",
            "branch": eff_branch,
            "xano_object_id": next_oid,
            "parent_artifact_id": None,
            "name": name.strip(),
            "description": description,
            "docs": docs,
            "swagger_enabled": swagger if swagger is not None else None,
            "guid": None,
            "canonical_url": None,
            "access": None,
            "size_bytes": None,
            "content_type": None,
            "download_url": None,
            "password_protected": None,
            "payload": {},
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }

        artifacts.append(row)
        _save("xano_workspace_artifacts.json", artifacts)

        _ensure_audit(endpoint, "OK", (time.time() - t0) * 1000.0, instance_id=inst.get("id"), workspace_id_val=ws.get("id"), artifact_id=new_id)
        return {"api_group": row, "meta": {"instance_name": instance_name, "workspace": {"id": ws.get("id"), "xano_workspace_id": ws.get("xano_workspace_id")}}}
    except Exception as ex:
        _ensure_audit(endpoint, "INTERNAL_ERROR", (time.time() - t0) * 1000.0)
        return _err("CONFLICT", "Internal error", detail=str(ex))

