            return None, _err("NOT_FOUND", "Workspace not found")
        if ws.get("status") == "deleted":
            return None, _err("NOT_FOUND", "Workspace deleted")
        if ws.get("status") != "active":
            return None, _err("UNAUTHORIZED", f"Workspace not accessible (status={ws.get('status')})")
        return ws, None

    def _ensure_audit(endpoint, status, latency_ms, instance_id=None, workspace_id_val=None, artifact_id=None):
        audit = _load("xano_audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({
            "id": "aud_" + uuid.uuid4().hex,
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "instance_id": instance_id,
            "workspace_id": workspace_id_val,
            "artifact_id": artifact_id,
        })
        _save("xano_audit_log.json", audit)

    t0 = time.time()
    endpoint = "xano_delete_api_group"

    try:
        instances = _load("xano_instances.json")
        workspaces = _load("xano_workspaces.json")
        artifacts = _load("xano_workspace_artifacts.json")

        inst, err = _get_instance(instances, instance_name)
        if err:
            _ensure_audit(endpoint, err["error"]["code"], (time.time() - t0) * 1000.0)
            return err

        ws, err = _resolve_workspace(workspaces, inst, workspace_id)
        if err:
            _ensure_audit(endpoint, err["error"]["code"], (time.time() - t0) * 1000.0, instance_id=inst.get("id"))
            return err

        ag = None
        if isinstance(apigroup_id, str) and apigroup_id.strip() != "" and not apigroup_id.strip().isdigit():
            agid = apigroup_id.strip()
            ag = next((a for a in artifacts if a.get("id") == agid and a.get("workspace_id") == ws.get("id") and a.get("artifact_type") == "api_group"), None)
        else:
            n, e = _as_pos_int(apigroup_id, "apigroup_id")
            if e:
                _ensure_audit(endpoint, e["error"]["code"], (time.time() - t0) * 1000.0, instance_id=inst.get("id"), workspace_id_val=ws.get("id"))
                return e
            if n is None:
                _ensure_audit(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000.0, instance_id=inst.get("id"), workspace_id_val=ws.get("id"))
                return _err("VALIDATION_ERROR", "apigroup_id is required")
            ag = next((a for a in artifacts if a.get("workspace_id") == ws.get("id") and a.get("artifact_type") == "api_group" and a.get("xano_object_id") == n), None)

        if not ag:
            _ensure_audit(endpoint, "NOT_FOUND", (time.time() - t0) * 1000.0, instance_id=inst.get("id"), workspace_id_val=ws.get("id"))
            return _err("NOT_FOUND", "API group not found")

        if ag.get("status") == "deleted":
            # idempotent delete
            _ensure_audit(endpoint, "OK", (time.time() - t0) * 1000.0, instance_id=inst.get("id"), workspace_id_val=ws.get("id"), artifact_id=ag.get("id"))
            return {"result": {"deleted": True, "already_deleted": True, "api_group_id": ag.get("id")}}

        now = _now()
        ag["status"] = "deleted"
        ag["updated_at"] = now

        # Cascade delete child APIs
        deleted_children = 0
        for a in artifacts:
            if a.get("artifact_type") == "api" and a.get("workspace_id") == ws.get("id") and a.get("parent_artifact_id") == ag.get("id"):
                if a.get("status") != "deleted":
                    a["status"] = "deleted"
                    a["updated_at"] = now
                    deleted_children += 1

        _save("xano_workspace_artifacts.json", artifacts)

        _ensure_audit(endpoint, "OK", (time.time() - t0) * 1000.0, instance_id=inst.get("id"), workspace_id_val=ws.get("id"), artifact_id=ag.get("id"))
        return {"result": {"deleted": True, "api_group_id": ag.get("id"), "deleted_child_apis": deleted_children}}
    except Exception as ex:
        _ensure_audit(endpoint, "INTERNAL_ERROR", (time.time() - t0) * 1000.0)
        return _err("CONFLICT", "Internal error", detail=str(ex))

def xano_update_api_group_security(instance_name, workspace_id, apigroup_id, guid=None, canonical=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_update_api_group_security"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _to_pos_int(val, field):
        if isinstance(val, bool) or val is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if isinstance(val, int):
            i = val
        elif isinstance(val, str):
            s = val.strip()
            if s == "" or not s.isdigit():
                return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
            i = int(s)
        else:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if i <= 0:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        return i, None

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "instance_name": instance_name if isinstance(instance_name, str) else None,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(instance_name, str) or not instance_name.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name must be a non-empty string")

    ws_id, e = _to_pos_int(workspace_id, "workspace_id")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e
    ag_id, e = _to_pos_int(apigroup_id, "apigroup_id")
    if e:
        _log("error", "VALIDATION_ERROR")
        return e

    if guid is not None and not isinstance(guid, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "guid must be a string")
    if canonical is not None and not isinstance(canonical, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "canonical must be a string")
    if guid is None and canonical is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one of guid or canonical must be provided")

    instances = _load("xano_instances.json")
    inst = next((r for r in instances if r.get("instance_name") == instance_name and r.get("status") == "active"), None)
    if not inst:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found or not active")

    workspaces = _load("xano_workspaces.json")
    ws = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_id and w.get("status") != "deleted"), None)
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    artifacts = _load("xano_workspace_artifacts.json")
    group = next((a for a in artifacts
                  if a.get("workspace_id") == ws.get("id")
                  and a.get("artifact_type") == "api_group"
                  and a.get("xano_object_id") == ag_id
                  and a.get("status") != "deleted"), None)
    if not group:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "API group not found")

    # Enforce guid uniqueness among non-deleted rows of the same artifact_type in workspace
    if guid is not None:
        guid_norm = guid.strip()
        # Treat empty string as clearing the guid
        if guid_norm == "":
            guid_norm = ""
        else:
            conflict = next((a for a in artifacts
                             if a.get("workspace_id") == ws.get("id")
                             and a.get("artifact_type") == "api_group"
                             and a.get("status") != "deleted"
                             and a.get("id") != group.get("id")
                             and (a.get("guid") or "") == guid_norm), None)
            if conflict:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "guid must be unique among non-deleted API groups in the workspace")

    # Mutate
    now = _now()
    if guid is not None:
        group["guid"] = guid.strip()
    if canonical is not None:
        group["canonical_url"] = canonical.strip()
    group["updated_at"] = now

    _save("xano_workspace_artifacts.json", artifacts)
    _log("ok")
    return {"data": group}

def xano_browse_apis_in_group(instance_name, workspace_id, apigroup_id, page=None, per_page=None, search=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, uuid, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_browse_apis_in_group"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error=None, **ctx):
        logs = _ensure_logs()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "context": ctx or {}
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, float):
            if v.is_integer() and int(v) > 0:
                return int(v), None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)

    def _is_ulid_prefix(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_")

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    if page is None:
        page = 1
    if per_page is None:
        per_page = 50
    if not isinstance(page, int) or page < 1:
        e = _err("VALIDATION_ERROR", "page must be an integer >= 1.", field="page")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if not isinstance(per_page, int) or per_page < 1 or per_page > 200:
        e = _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 200.", field="per_page")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if order is not None and order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'.", field="order")
        _log("error", error=e["error"], instance_name=instance_name)
        return e

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    artifacts = _load("xano_workspace_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    # workspace_id is numeric (per tool description) but accept ULID too to be consistent with store
    ws_row = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted"), None)
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    # Resolve api_group by numeric xano_object_id or ULID id
    group_row = None
    group_id = None
    if _is_ulid_prefix(apigroup_id, "xna"):
        group_row = next((a for a in artifacts if a.get("id") == apigroup_id and a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "api_group" and a.get("status") != "deleted"), None)
        group_id = group_row.get("id") if group_row else None
    else:
        gid_num, gerr = _as_positive_int(apigroup_id, "apigroup_id")
        if gerr:
            _log("error", error=gerr["error"], instance_name=instance_name, apigroup_id=apigroup_id)
            return gerr
        group_row = next((a for a in artifacts if a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "api_group" and a.get("xano_object_id") == gid_num and a.get("status") != "deleted"), None)
        group_id = group_row.get("id") if group_row else None

    if not group_row:
        e = _err("NOT_FOUND", "API group not found.", field="apigroup_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, apigroup_id=apigroup_id)
        return e

    apis = [a for a in artifacts if a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "api" and a.get("status") != "deleted" and a.get("parent_artifact_id") == group_id]

    if isinstance(search, str) and search.strip():
        q = search.strip().lower()
        def _m(a):
            n = a.get("name") or ""
            d = a.get("description") or ""
            return (q in str(n).lower()) or (q in str(d).lower())
        apis = [a for a in apis if _m(a)]

    sort_field = sort if isinstance(sort, str) and sort.strip() else "created_at"
    if sort_field not in ("created_at", "updated_at", "name"):
        sort_field = "created_at"
    ord_dir = order or "asc"

    def _key(a):
        v = a.get(sort_field)
        if sort_field in ("created_at", "updated_at"):
            dt = _parse_iso(v) if isinstance(v, str) else None
            return dt or datetime.datetime(1970, 1, 1)
        return str(v or "").lower()

    apis.sort(key=_key, reverse=(ord_dir == "desc"))

    total = len(apis)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = apis[start:end] if start < total else []
    total_pages = int(math.ceil(total / float(per_page))) if per_page else 0

    resp = {
        "data": page_rows,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "total_pages": total_pages,
            "has_more": end < total
        }
    }
    _log("ok", instance_name=instance_name, workspace_id=workspace_id, apigroup_id=apigroup_id, page=page, per_page=per_page)
    return resp

