            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, float):
            if v.is_integer() and int(v) > 0:
                return int(v), None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)

    def _is_ulid_prefix(s, prefix):
        return isinstance(s, str) and s.startswith(prefix + "_")

    def _gen_id(prefix):
        return f"{prefix}_" + uuid.uuid4().hex[:26]

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string.", field="description")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if docs is not None and not isinstance(docs, str):
        e = _err("VALIDATION_ERROR", "docs must be a string.", field="docs")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if swagger_enabled is not None and not isinstance(swagger_enabled, bool):
        e = _err("VALIDATION_ERROR", "swagger_enabled must be a boolean.", field="swagger_enabled")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if access is not None and access not in ("public", "private"):
        e = _err("VALIDATION_ERROR", "access must be 'public' or 'private'.", field="access")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if guid is not None and not isinstance(guid, str):
        e = _err("VALIDATION_ERROR", "guid must be a string.", field="guid")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if canonical is not None and not isinstance(canonical, str):
        e = _err("VALIDATION_ERROR", "canonical must be a string.", field="canonical")
        _log("error", error=e["error"], instance_name=instance_name)
        return e
    if payload is not None and not isinstance(payload, dict):
        e = _err("VALIDATION_ERROR", "payload must be an object.", field="payload")
        _log("error", error=e["error"], instance_name=instance_name)
        return e

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    artifacts = _load("xano_workspace_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    ws_row = None
    if _is_ulid_prefix(workspace_id, "xnw"):
        ws_row = next((w for w in workspaces if w.get("id") == workspace_id and w.get("instance_id") == inst.get("id") and w.get("status") != "deleted"), None)
    else:
        ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
        if werr:
            _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
            return werr
        ws_row = next((w for w in workspaces if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num and w.get("status") != "deleted"), None)
    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    # Resolve api_group
    group_row = None
    group_artifact_id = None
    group_xano_id = None
    if _is_ulid_prefix(apigroup_id, "xna"):
        group_row = next((a for a in artifacts if a.get("id") == apigroup_id and a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "api_group" and a.get("status") != "deleted"), None)
    else:
        group_xano_id, gerr = _as_positive_int(apigroup_id, "apigroup_id")
        if gerr:
            _log("error", error=gerr["error"], instance_name=instance_name, apigroup_id=apigroup_id)
            return gerr
        group_row = next((a for a in artifacts if a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "api_group" and a.get("xano_object_id") == group_xano_id and a.get("status") != "deleted"), None)

    if not group_row:
        e = _err("NOT_FOUND", "API group not found.", field="apigroup_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id, apigroup_id=apigroup_id)
        return e

    group_artifact_id = group_row.get("id")
    branch = group_row.get("branch") or ws_row.get("branch_default")

    # guid uniqueness among non-deleted apis within workspace when present
    if guid is not None and guid.strip():
        for a in artifacts:
            if a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "api" and a.get("status") != "deleted" and a.get("guid") == guid:
                e = _err("CONFLICT", "guid must be unique among non-deleted APIs in the workspace.", field="guid")
                _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
                return e

    # Create new api artifact; xano_object_id allocate next int in workspace for api type
    existing_ids = [a.get("xano_object_id") for a in artifacts if a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "api" and isinstance(a.get("xano_object_id"), int)]
    next_api_id = (max(existing_ids) + 1) if existing_ids else 1

    now = _now()
    api_row = {
        "id": _gen_id("xna"),
        "workspace_id": ws_row.get("id"),
        "artifact_type": "api",
        "branch": branch,
        "xano_object_id": next_api_id,
        "parent_artifact_id": group_artifact_id,
        "name": name.strip(),
        "description": description,
        "docs": docs,
        "swagger_enabled": swagger_enabled,
        "guid": guid,
        "canonical_url": canonical,
        "access": access,
        "size_bytes": None,
        "content_type": None,
        "download_url": None,
        "password_protected": None,
        "payload": copy.deepcopy(payload) if isinstance(payload, dict) else (payload if payload is not None else None),
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    artifacts.append(api_row)
    _save("xano_workspace_artifacts.json", artifacts)
    _log("ok", instance_name=instance_name, workspace_id=workspace_id, apigroup_id=apigroup_id, api_id=api_row["id"])
    return {"data": api_row}

def xano_update_api(instance_name, workspace_id, apigroup_id, api_id, name=None, description=None, docs=None, swagger_enabled=None, access=None, canonical=None, payload=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_update_api"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None, **meta):
        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "instance_name": instance_name,
            "workspace_id": str(workspace_id) if workspace_id is not None else None,
            "status": status,
            "message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("xano_request_logs.json", logs)

    def _parse_pos_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if isinstance(v, int):
            n = v
        elif isinstance(v, str):
            s = v.strip()
            if s == "" or not s.isdigit():
                return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
            try:
                n = int(s)
            except ValueError:
                return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        else:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if n <= 0:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        return n, None

    def _validate_optional_str(v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string")
        return None

    def _resolve_instance_active(instances, inst_name):
        if not isinstance(inst_name, str) or not inst_name.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        matches = [r for r in instances if r.get("instance_name") == inst_name]
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) != 1:
            if any(r.get("status") == "disabled" for r in matches):
                return None, _err("NOT_FOUND", "Instance is disabled")
            if any(r.get("status") == "deleted" for r in matches):
                return None, _err("NOT_FOUND", "Instance is deleted")
            return None, _err("NOT_FOUND", "Instance not found")
        return active[0], None

    # Basic validation
    ws_id, e = _parse_pos_int(workspace_id, "workspace_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    ag_id, e = _parse_pos_int(apigroup_id, "apigroup_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    a_id, e = _parse_pos_int(api_id, "api_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    for v, f in [(name, "name"), (description, "description"), (docs, "docs"), (canonical, "canonical")]:
        e = _validate_optional_str(v, f)
        if e:
            _log("error", e["error"]["message"], code=e["error"]["code"])
            return e
    if swagger_enabled is not None and not isinstance(swagger_enabled, bool):
        e = _err("VALIDATION_ERROR", "swagger_enabled must be a boolean")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    if access is not None:
        if not isinstance(access, str) or access not in ("public", "private"):
            e = _err("VALIDATION_ERROR", "access must be one of: public, private")
            _log("error", e["error"]["message"], code=e["error"]["code"])
            return e
    if payload is not None and not isinstance(payload, dict):
        e = _err("VALIDATION_ERROR", "payload must be an object")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    # Resolve instance/workspace/api group/api
    instances = _load("xano_instances.json")
    workspaces = _load("xano_workspaces.json")
    artifacts = _load("xano_workspace_artifacts.json")

    inst, e = _resolve_instance_active(instances, instance_name)
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    ws = None
    for r in workspaces if isinstance(workspaces, list) else []:
        if r.get("instance_id") == inst.get("id") and r.get("xano_workspace_id") == ws_id and r.get("status") != "deleted":
            ws = r
            break
    if not ws:
        e = _err("NOT_FOUND", "Workspace not found")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    api_group = None
    for r in artifacts if isinstance(artifacts, list) else []:
        if r.get("workspace_id") == ws.get("id") and r.get("artifact_type") == "api_group" and r.get("xano_object_id") == ag_id and r.get("status") != "deleted":
            api_group = r
            break
    if not api_group:
        e = _err("NOT_FOUND", "API group not found")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    api = None
    api_idx = None
    for i, r in enumerate(artifacts if isinstance(artifacts, list) else []):
        if r.get("workspace_id") == ws.get("id") and r.get("artifact_type") == "api" and r.get("xano_object_id") == a_id and r.get("status") != "deleted":
            if r.get("parent_artifact_id") == api_group.get("id"):
                api = r
                api_idx = i
                break
    if api is None:
        e = _err("NOT_FOUND", "API not found in the specified API group")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    # Update permitted fields
    changed = False
    if name is not None:
        artifacts[api_idx]["name"] = name
        changed = True
    if description is not None:
        artifacts[api_idx]["description"] = description
        changed = True
    if docs is not None:
        artifacts[api_idx]["docs"] = docs
        changed = True
    if swagger_enabled is not None:
        artifacts[api_idx]["swagger_enabled"] = swagger_enabled
        changed = True
    if access is not None:
        artifacts[api_idx]["access"] = access
        changed = True
    if canonical is not None:
        artifacts[api_idx]["canonical_url"] = canonical
        changed = True
    if payload is not None:
        artifacts[api_idx]["payload"] = payload
        changed = True

    if not changed:
        # No-op update should still behave like vendor: return current object (effectively idempotent)
        artifacts[api_idx]["updated_at"] = artifacts[api_idx].get("updated_at") or _now()
    else:
        artifacts[api_idx]["updated_at"] = _now()

    _save("xano_workspace_artifacts.json", artifacts)

    inst["last_discovered_at"] = _now()
    inst["updated_at"] = _now()
    for i, r in enumerate(instances if isinstance(instances, list) else []):
        if r.get("id") == inst.get("id"):
            instances[i] = inst
            break
    _save("xano_instances.json", instances)

    out = artifacts[api_idx]
    _log("ok")
    return {"api": out}

def xano_delete_api(instance_name, workspace_id, apigroup_id, api_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_delete_api"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None, **meta):
        logs = _load("xano_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "instance_name": instance_name,
            "workspace_id": str(workspace_id) if workspace_id is not None else None,
            "status": status,
            "message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("xano_request_logs.json", logs)

    def _parse_pos_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if isinstance(v, int):
            n = v
        elif isinstance(v, str):
            s = v.strip()
            if s == "" or not s.isdigit():
                return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
            try:
                n = int(s)
            except ValueError:
                return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        else:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if n <= 0:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        return n, None

    def _resolve_instance_active(instances, inst_name):
        if not isinstance(inst_name, str) or not inst_name.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        matches = [r for r in instances if r.get("instance_name") == inst_name]
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) != 1:
            if any(r.get("status") == "disabled" for r in matches):
                return None, _err("NOT_FOUND", "Instance is disabled")
            if any(r.get("status") == "deleted" for r in matches):
                return None, _err("NOT_FOUND", "Instance is deleted")
            return None, _err("NOT_FOUND", "Instance not found")
        return active[0], None

    ws_id, e = _parse_pos_int(workspace_id, "workspace_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    ag_id, e = _parse_pos_int(apigroup_id, "apigroup_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    a_id, e = _parse_pos_int(api_id, "api_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    instances = _load("xano_instances.json")
    workspaces = _load("xano_workspaces.json")
    artifacts = _load("xano_workspace_artifacts.json")

    inst, e = _resolve_instance_active(instances, instance_name)
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    ws = None
    for r in workspaces if isinstance(workspaces, list) else []:
        if r.get("instance_id") == inst.get("id") and r.get("xano_workspace_id") == ws_id and r.get("status") != "deleted":
            ws = r
            break
    if not ws:
        e = _err("NOT_FOUND", "Workspace not found")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    api_group = None
    for r in artifacts if isinstance(artifacts, list) else []:
        if r.get("workspace_id") == ws.get("id") and r.get("artifact_type") == "api_group" and r.get("xano_object_id") == ag_id and r.get("status") != "deleted":
            api_group = r
            break
    if not api_group:
        e = _err("NOT_FOUND", "API group not found")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    api = None
    api_idx = None
    for i, r in enumerate(artifacts if isinstance(artifacts, list) else []):
        if r.get("workspace_id") == ws.get("id") and r.get("artifact_type") == "api" and r.get("xano_object_id") == a_id and r.get("status") != "deleted":
            if r.get("parent_artifact_id") == api_group.get("id"):
                api = r
                api_idx = i
                break
    if api is None:
        e = _err("NOT_FOUND", "API not found in the specified API group")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    # Transition active -> deleted
    if api.get("status") == "deleted":
        # idempotent-ish: but "no success without effect" doesn't apply because we matched a row; still return deletion result
        pass
    else:
        api["status"] = "deleted"
        api["updated_at"] = _now()
        artifacts[api_idx] = api
        _save("xano_workspace_artifacts.json", artifacts)

    inst["last_discovered_at"] = _now()
    inst["updated_at"] = _now()
    for i, r in enumerate(instances if isinstance(instances, list) else []):
        if r.get("id") == inst.get("id"):
            instances[i] = inst
            break
    _save("xano_instances.json", instances)

    _log("ok")
    return {"deleted": True, "api": api}

