            "endpoint": endpoint,
            "instance_name": instance_name,
            "workspace_id": str(workspace_id) if workspace_id is not None else None,
            "status": status,
            "message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("xano_request_logs.json", logs)

    def _parse_pos_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if isinstance(v, int):
            n = v
        elif isinstance(v, str):
            s = v.strip()
            if s == "" or not s.isdigit():
                return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
            try:
                n = int(s)
            except ValueError:
                return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        else:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        if n <= 0:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer")
        return n, None

    def _resolve_instance_active(instances, inst_name):
        if not isinstance(inst_name, str) or not inst_name.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string")
        matches = [r for r in instances if r.get("instance_name") == inst_name]
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) != 1:
            if any(r.get("status") == "disabled" for r in matches):
                return None, _err("NOT_FOUND", "Instance is disabled")
            if any(r.get("status") == "deleted" for r in matches):
                return None, _err("NOT_FOUND", "Instance is deleted")
            return None, _err("NOT_FOUND", "Instance not found")
        return active[0], None

    ws_id, e = _parse_pos_int(workspace_id, "workspace_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    ag_id, e = _parse_pos_int(apigroup_id, "apigroup_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    a_id, e = _parse_pos_int(api_id, "api_id")
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e
    if not isinstance(guid, str):
        e = _err("VALIDATION_ERROR", "guid must be a string")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    instances = _load("xano_instances.json")
    workspaces = _load("xano_workspaces.json")
    artifacts = _load("xano_workspace_artifacts.json")

    inst, e = _resolve_instance_active(instances, instance_name)
    if e:
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    ws = None
    for r in workspaces if isinstance(workspaces, list) else []:
        if r.get("instance_id") == inst.get("id") and r.get("xano_workspace_id") == ws_id and r.get("status") != "deleted":
            ws = r
            break
    if not ws:
        e = _err("NOT_FOUND", "Workspace not found")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    api_group = None
    for r in artifacts if isinstance(artifacts, list) else []:
        if r.get("workspace_id") == ws.get("id") and r.get("artifact_type") == "api_group" and r.get("xano_object_id") == ag_id and r.get("status") != "deleted":
            api_group = r
            break
    if not api_group:
        e = _err("NOT_FOUND", "API group not found")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    api = None
    api_idx = None
    for i, r in enumerate(artifacts if isinstance(artifacts, list) else []):
        if r.get("workspace_id") == ws.get("id") and r.get("artifact_type") == "api" and r.get("xano_object_id") == a_id and r.get("status") != "deleted":
            if r.get("parent_artifact_id") == api_group.get("id"):
                api = r
                api_idx = i
                break
    if api is None:
        e = _err("NOT_FOUND", "API not found in the specified API group")
        _log("error", e["error"]["message"], code=e["error"]["code"])
        return e

    # GUID uniqueness among non-deleted APIs within the workspace when present
    if guid.strip() != "":
        for r in artifacts if isinstance(artifacts, list) else []:
            if r.get("workspace_id") != ws.get("id"): 
                continue
            if r.get("artifact_type") != "api":
                continue
            if r.get("status") == "deleted":
                continue
            if r.get("id") == api.get("id"):
                continue
            if r.get("guid") == guid:
                e = _err("CONFLICT", "guid must be unique among non-deleted APIs within the workspace")
                _log("error", e["error"]["message"], code=e["error"]["code"])
                return e

    artifacts[api_idx]["guid"] = guid
    artifacts[api_idx]["updated_at"] = _now()
    _save("xano_workspace_artifacts.json", artifacts)

    inst["last_discovered_at"] = _now()
    inst["updated_at"] = _now()
    for i, r in enumerate(instances if isinstance(instances, list) else []):
        if r.get("id") == inst.get("id"):
            instances[i] = inst
            break
    _save("xano_instances.json", instances)

    _log("ok")
    return {"api": artifacts[api_idx]}

