        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name is required and must be a non-empty string.")
    instance_name = instance_name.strip()
    if len(instance_name) > 128:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name is too long.", max_length=128)

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []

    matches = [r for r in instances if isinstance(r, dict) and r.get("instance_name") == instance_name]
    # Must resolve to exactly one active for tools that include instance_name, but this tool enables disabled.
    # Here: if none => NOT_FOUND; if multiple => CONFLICT (uniqueness violated).
    if len(matches) == 0:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No instance found for the given instance_name.")
    if len(matches) > 1:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Multiple instances match this instance_name; datastore violates uniqueness.")

    inst = matches[0]
    status = inst.get("status")
    if status == "active":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Instance is already active.")
    if status == "deleted":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Instance is deleted and cannot be enabled.")
    if status != "disabled":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Instance has an invalid status.", status=status)

    # Ambient auth: if there's any active instance-management capability, allow.
    # This datastore has no explicit auth/roles; per contract, do not refuse well-formed calls.
    inst["status"] = "active"
    inst["updated_at"] = now
    if inst.get("created_at") in (None, ""):
        inst["created_at"] = now

    _save("xano_instances.json", instances)
    _log("ok")

    return {"instance": inst}

def xano_suspend_workspace(instance_name, workspace_id, **_extra):
