    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_suspend_workspace"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(logs, list):
            logs.append(row)
        else:
            logs = [row]
        _save("request_logs.json", logs)

    # Validate instance_name
    if not isinstance(instance_name, str) or not instance_name.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_name is required and must be a non-empty string.")
    instance_name = instance_name.strip()

    # Validate workspace_id as positive int
    if isinstance(workspace_id, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a positive integer (string or number).")
    if isinstance(workspace_id, int):
        wid = workspace_id
    elif isinstance(workspace_id, str) and workspace_id.isdigit():
        try:
            wid = int(workspace_id)
        except ValueError:
            wid = None
    else:
        wid = None
    if wid is None or wid <= 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a positive integer (string or number).")

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst_matches = [r for r in instances if isinstance(r, dict) and r.get("instance_name") == instance_name]
    if len(inst_matches) == 0:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.")
    if len(inst_matches) > 1:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Multiple instances match this instance_name; datastore violates uniqueness.")
    inst = inst_matches[0]
    if inst.get("status") != "active":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Instance is not active.", status=inst.get("status"))

    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    ws_matches = [
        w for w in workspaces
        if isinstance(w, dict)
        and w.get("instance_id") == inst.get("id")
        and w.get("xano_workspace_id") == wid
    ]
    if len(ws_matches) == 0:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for this instance/workspace_id.")
    if len(ws_matches) > 1:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Multiple workspaces match this instance/workspace_id; datastore violates uniqueness.")

    ws = ws_matches[0]
    st = ws.get("status")
    if st == "suspended":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Workspace is already suspended.")
    if st == "deleted":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Workspace is deleted and cannot be suspended.")
    if st != "active":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace is not active.", status=st)

    # Transition active -> suspended
    ws["status"] = "suspended"
    ws["updated_at"] = now
    if ws.get("created_at") in (None, ""):
        ws["created_at"] = now

    _save("xano_workspaces.json", workspaces)
    _log("ok")
    return {"workspace": ws}

def xano_activate_workspace(instance_name, workspace_id, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_activate_workspace"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error=None, **ctx):
        logs = _ensure_logs()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "context": ctx or {}
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _ensure_logs()
        nowdt = datetime.datetime.utcnow()

        if isinstance(rate, int) and rate > 0:
            cutoff = nowdt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs:
                rdt = _parse_iso(r.get("timestamp"))
                if rdt and rdt >= cutoff:
                    recent += 1
            if recent >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")

        if isinstance(quota, int) and quota > 0:
            day = nowdt.strftime("%Y-%m-%d")
            used = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts[:10] == day:
                    used += 1
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_instance(instances, iname):
        if not isinstance(iname, str) or not iname.strip():
            return None, _err("VALIDATION_ERROR", "instance_name must be a non-empty string.", field="instance_name")
        matches = [r for r in instances if r.get("instance_name") == iname]
        if not matches:
            return None, _err("NOT_FOUND", "Instance not found.", field="instance_name")
        active = [r for r in matches if r.get("status") == "active"]
        if len(active) == 1:
            return active[0], None
        if len(active) == 0:
            st = matches[0].get("status")
            return None, _err("NOT_FOUND", f"Instance is not active (status={st}).", field="instance_name")
        return None, _err("CONFLICT", "Multiple active instances matched instance_name.", field="instance_name")

    def _as_positive_int(v, field):
        if isinstance(v, bool) or v is None:
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer (string or number).", field=field)
        if isinstance(v, int):
            if v > 0:
                return v, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer.", field=field)
        if isinstance(v, str):
            s = v.strip()
            if re.fullmatch(r"[0-9]+", s or ""):
                n = int(s)
                if n > 0:
                    return n, None
            return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer (string or number).", field=field)
        if isinstance(v, float):
            if v.is_integer() and int(v) > 0:
                return int(v), None
        return None, _err("VALIDATION_ERROR", f"{field} must be a positive integer (string or number).", field=field)

    lim = _check_limits()
    if lim:
        _log("error", error=lim["error"], instance_name=instance_name)
        return lim

    instances = _load("xano_instances.json")
    if not isinstance(instances, list):
        instances = []
    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    inst, err = _resolve_instance(instances, instance_name)
    if err:
        _log("error", error=err["error"], instance_name=instance_name)
        return err

    ws_num, werr = _as_positive_int(workspace_id, "workspace_id")
    if werr:
        _log("error", error=werr["error"], instance_name=instance_name, workspace_id=workspace_id)
        return werr

    # Find workspace by numeric xano_workspace_id within instance
    ws_idx = None
    ws_row = None
    for i, w in enumerate(workspaces):
        if w.get("instance_id") == inst.get("id") and w.get("xano_workspace_id") == ws_num:
            ws_idx = i
            ws_row = w
            break

    if not ws_row:
        e = _err("NOT_FOUND", "Workspace not found.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    st = ws_row.get("status")
    if st == "deleted":
        e = _err("CONFLICT", "Workspace is deleted and cannot be activated.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e
    if st == "active":
        e = _err("CONFLICT", "Workspace is already active.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e
    if st != "suspended":
        e = _err("INVALID_TRANSITION", f"Cannot activate workspace from status '{st}'.", field="workspace_id")
        _log("error", error=e["error"], instance_name=instance_name, workspace_id=workspace_id)
        return e

    now = _now()
    workspaces[ws_idx]["status"] = "active"
    workspaces[ws_idx]["updated_at"] = now
    _save("xano_workspaces.json", workspaces)

    _log("ok", instance_name=instance_name, workspace_id=workspace_id)
    return {"data": workspaces[ws_idx]}

def xano_retry_workspace_artifact(workspace_id, artifact_id, **_extra):
    import json, os, datetime, time, uuid, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0523000" if __import__("os").path.isdir("./environment_mix/0523000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "xano_retry_workspace_artifact"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(logs, list):
            logs.append(row)
        else:
            logs = [row]
        _save("request_logs.json", logs)

    def _to_pos_int(v, name):
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v if v > 0 else None
        if isinstance(v, str) and v.isdigit():
            try:
                iv = int(v)
                return iv if iv > 0 else None
            except ValueError:
                return None
        return None

    wid = _to_pos_int(workspace_id, "workspace_id")
    aid = _to_pos_int(artifact_id, "artifact_id")
    if wid is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a positive integer (string or number).")
    if aid is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "artifact_id must be a positive integer (string or number).")

    workspaces = _load("xano_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_rows = [w for w in workspaces if isinstance(w, dict) and w.get("xano_workspace_id") == wid and w.get("status") != "deleted"]
    if len(ws_rows) == 0:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    # If multiple across instances (shouldn't happen), pick any active/suspended one deterministically
    ws_rows.sort(key=lambda r: (r.get("status") != "active", r.get("id") or ""))
    ws = ws_rows[0]
    if ws.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace is deleted.")
    workspace_internal_id = ws.get("id")

    artifacts = _load("xano_workspace_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    # artifact primary key id is string in schema, but tool accepts int/string digits. Match by stringified.
    aid_str = str(aid)
    matches = [
        a for a in artifacts
        if isinstance(a, dict)
        and a.get("id") == aid_str
        and a.get("workspace_id") == workspace_internal_id
    ]
    if len(matches) == 0:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Artifact not found for this workspace.")

    art = matches[0]
    st = art.get("status")
    if st != "failed":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Artifact is not in failed state and cannot be retried.", status=st)

    # Only supported for types that have processing lifecycle; allow export_job and request_history by rule text,
    # but typically retry is for export_job. We'll restrict to export_job to avoid illegal semantics.
    if art.get("artifact_type") not in ("export_job",):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Retry is not supported for this artifact type.", artifact_type=art.get("artifact_type"))

    # Transition failed -> processing
    art["status"] = "processing"
    art["updated_at"] = now
    if art.get("created_at") in (None, ""):
        art["created_at"] = now

    # Observable dynamics: simulate eventual processing completion sometimes immediately.
    # If it is an export job, transition to active with download_url or to failed.
    # This persists state changes.
    payload = art.get("payload")
    if not isinstance(payload, dict) and payload is not None:
        payload = {"_raw": payload}
    if payload is None:
        payload = {}
    payload["retried_at"] = now
    art["payload"] = payload

    # Decide completion outcome deterministically-ish: based on id hash and current time bucket.
    # Keep it stable enough for offline testing while still dynamic.
    seed = (aid * 1315423911) ^ int(time.time() // 5)
    rng = random.Random(seed)
    # 70% chance success
    if rng.random() < 0.7:
        art["status"] = "active"
        # Generate a plausible local download URL if absent
        if not art.get("download_url"):
            art["download_url"] = f"file:///app/database/exports/{workspace_internal_id}/{aid_str}.zip"
        art["updated_at"] = now
    else:
        art["status"] = "failed"
        art["updated_at"] = now
        payload["last_error"] = payload.get("last_error") or "Retry attempt failed during processing."
        art["payload"] = payload

    _save("xano_workspace_artifacts.json", artifacts)
    _log("ok")
    return {"artifact": art}
